/** All translations for zizhitongjian ch.039 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "【漢紀三十一】起昭陽協洽，盡閼逢涒灘，凡二年。", literal: "【Han Records 31】 From Zhaoyang Xiehe through Yanfeng Youtan—in all, two years.", idiomatic: "【Han Records 31】 From the first year of the Zhaoyang cycle through the last year of the Yanfeng cycle—two years in all." },
  { zh: "春，正月，甲子朔，漢兵與下江兵共攻甄阜、梁丘賜，斬之，殺士卒二萬餘人。", literal: "In spring, the first month, on the new moon of jiazi, Han troops together with the Xiajiang army jointly attacked Zhen Fu and Liang Qiumo, beheaded them, and killed more than twenty thousand soldiers.", idiomatic: "In spring, in the first month, on the new moon of jiazi, Han troops and the Xiajiang army jointly attacked Zhen Fu and Liang Qiumo, beheaded them, and killed more than twenty thousand soldiers." },
  { zh: "王莽納言將軍嚴尤、秩宗將軍陳茂引兵欲據宛，劉縯與戰於淯陽下，大破之，遂圍宛。", literal: "Wang Mang's Receiver of Words General Yan You and Rank-and-Ritual General Chen Mao led troops wishing to hold Wan; Liu Yan fought them below Zhuyang, routed them utterly, and thereupon besieged Wan.", idiomatic: "Wang Mang's Receiver of Words General Yan You and Rank-and-Ritual General Chen Mao led troops to hold Wan; Liu Yan fought them at Zhuyang, routed them utterly, and besieged Wan." },
  { zh: "先是，青、徐賊眾雖數十萬人，訖無文書、號令、旌旗、部曲。", literal: "Earlier, though the bandit hosts of Qing and Xu numbered several hundred thousand, in the end they had no documents, orders, banners, or organized companies.", idiomatic: "Earlier, though the rebel hosts of Qing and Xu numbered in the hundreds of thousands, they had no written orders, commands, banners, or organized regiments." },
  { zh: "及漢兵起，皆稱將軍，攻城略地，移書稱說。", literal: "When Han troops rose, all called themselves generals, stormed cities and seized territory, and sent letters proclaiming their cause.", idiomatic: "When the Han armies rose, all styled themselves generals, stormed cities and seized territory, and circulated proclamations setting forth their cause." },
  { zh: "莽聞之，始懼。", literal: "Mang heard of it and for the first time grew afraid.", idiomatic: "Wang Mang heard of it and for the first time grew afraid." },
  { zh: "舂陵戴侯曾孫玄在平林兵中，號更始將軍。", literal: "Xuan, great-grandson of Marquis Dai of Chunling, was among the Pinglin troops and styled himself General Gengshi.", idiomatic: "Liu Xuan, great-grandson of Marquis Dai of Chunling, was among the Pinglin troops and styled himself General Gengshi." },
  { zh: "時漢兵已十餘萬，諸將議以兵多而無所統一，欲立劉氏以從人望。", literal: "At that time Han troops already exceeded a hundred thousand; the generals deliberated that with so many men and no single authority, they wished to set up a man of the Liu house to follow the people's hopes.", idiomatic: "Han forces already exceeded a hundred thousand; the generals argued that with so many men and no single leader, they ought to set up a Liu clansman to satisfy public expectation." },
  { zh: "南陽豪桀及王常等皆欲立劉縯；", literal: "Nanyang's powerful men and Wang Chang and others all wished to set up Liu Yan;", idiomatic: "Nanyang's powerful men and Wang Chang and others all wished to set up Liu Yan;" },
  { zh: "而新市、平林將帥樂放縱，憚縯威明，貪玄懦弱，先共定策立之，然後召縯示其議。", literal: "but the Xinshi and Pinglin commanders delighted in license, feared Yan's authority and clarity, and coveted Xuan's weakness; they first jointly fixed a plan to set him up, then summoned Yan to show him their decision.", idiomatic: "but the Xinshi and Pinglin commanders loved their license, feared Yan's authority and brilliance, and coveted Xuan's weakness; they fixed on enthroning him first, then summoned Yan to announce their decision." },
  { zh: "縯曰：「諸將軍幸欲尊立宗室，甚厚，然今赤眉起青、徐，眾數十萬，聞南陽立宗室，恐赤眉復有所立，王莽未滅而宗室相攻，是疑天下而自損權，非所以破莽也。", literal: "Yan said: \"Generals, you are gracious to wish to honor and set up the imperial house—very generous. Yet now the Red Eyebrows have risen in Qing and Xu, their host several hundred thousand; hearing that Nanyang has set up the imperial house, I fear the Red Eyebrows will set up another. With Wang Mang not yet destroyed, the imperial house attacks itself—this makes the realm doubt us and damages our own power; it is not the way to break Mang.\"", idiomatic: "Liu Yan said, \"Generals, it is generous of you to wish to raise a member of the imperial house. Yet the Red Eyebrows have risen in Qing and Xu with a host of hundreds of thousands; if they hear Nanyang has enthroned a Liu, they may set up another. With Wang Mang not yet destroyed, the clan turns on itself—the realm will doubt us and we will weaken our own hand. That is not how to break Wang Mang.\"" },
  { zh: "舂陵去宛三百里耳，遽自尊立，為天下准的，使後人得承吾敝，非計之善者也。", literal: "Chunling is only three hundred li from Wan; to hastily honor ourselves and become the realm's target, letting those who come after inherit our exhaustion—this is not a good plan.\"", idiomatic: "Chunling lies only three hundred li from Wan. To rush to enthrone ourselves and become the target of the realm, letting those who follow inherit our exhaustion—that is no good plan.\"" },
  { zh: "不如且稱王以號令，王勢亦足以斬諸將。", literal: "Better for the time being to style oneself king and command by that title; royal authority is also enough to behead any general.\"", idiomatic: "Better to style ourselves kings for now and command by that title—royal authority is enough to execute any general who disobeys.\"" },
  { zh: "若赤眉所立者賢，相率而往從之，必不奪吾爵位。", literal: "If whomever the Red Eyebrows set up is worthy, we can lead our men to follow him—they surely will not strip our rank.\"", idiomatic: "If whoever the Red Eyebrows enthrone proves worthy, we can lead our men to join him—they will not strip our rank.\"" },
  { zh: "若無所立，破莽，降赤眉，然後舉尊號，亦未晚也。", literal: "If they set up no one, we break Mang, subdue the Red Eyebrows, and only then take the supreme title—it is still not too late.\"", idiomatic: "If they enthrone no one, we destroy Wang Mang, subdue the Red Eyebrows, and only then take the imperial title—it will still not be too late.\"" },
  { zh: "」諸將多曰：「善！", literal: "\" Most of the generals said: \"Good!\"", idiomatic: "\" Most of the generals said, \"Well said!\"" },
  { zh: "」張卬拔劍擊地曰：「疑事無功，今日之議，不得有二！", literal: "\" Zhang Ang drew his sword and struck the ground, saying: \"Doubting affairs achieves nothing—today's deliberation admits no second choice!\"", idiomatic: "\" Zhang Ang drew his sword and struck the ground, saying, \"Hesitation accomplishes nothing—today's deliberation admits no second choice!\"" },
  { zh: "」眾皆從之。", literal: "\" The host all followed him.", idiomatic: "\" The assembly assented." },
  { zh: "二月，辛巳朔，設壇場於淯水上沙中，玄即皇帝位，南面立，朝群臣；", literal: "In the second month, on the new moon of xinsi, they set an altar on the sand midstream in the Ru River; Xuan then took the emperor's position, stood facing south, and held court before the host of ministers;", idiomatic: "In the second month, on the new moon of xinsi, they raised an altar on the sandbars of the Ru River; Liu Xuan took the throne, faced south, and received the ministers in audience;" },
  { zh: "羞愧流汗，舉手不能言。", literal: "ashamed, sweating, he raised his hands but could not speak.", idiomatic: "sweating with shame, he raised his hands but could not speak." },
  { zh: "於是大赦，改元，以族父良為國三老，王匡為定國上公，王鳳為成國上公，朱鮪為大司馬，劉縯為大司徒，陳牧為大司空，餘皆九卿將軍。", literal: "Thereupon a great amnesty was proclaimed and the era name changed; he made his clansman uncle Liu Liang Grand Mentor of the State, Wang Kuang Duke Who Settles the State, Wang Feng Duke Who Completes the State, Zhu Wei Grand Marshal, Liu Yan Grand Minister of Education, Chen Mu Grand Minister of Works—the rest all nine ministers or generals.", idiomatic: "A great amnesty followed and the era name was changed to Gengshi. He appointed his clansman uncle Liu Liang Grand Mentor of the State, Wang Kuang Duke Who Settles the State, Wang Feng Duke Who Completes the State, Zhu Wei Grand Marshal, Liu Yan Grand Minister of Education, Chen Mu Grand Minister of Works—the rest received ranks as nine ministers or generals." },
  { zh: "由是豪桀失望，多不服。", literal: "From this the powerful men were disappointed; many did not submit.", idiomatic: "The regional strongmen were disappointed; many refused to submit." },
  { zh: "王莽欲外示自安，乃染其鬚髮，立杜陵史諶女為皇后；", literal: "Wang Mang wished outwardly to show himself at ease; he therefore dyed his beard and hair, and set up the daughter of Du-ling clerk Shi Chen as empress;", idiomatic: "Wang Mang wished to appear at ease; he dyed his beard and hair and installed the daughter of Du-ling clerk Shi Chen as empress;" },
  { zh: "置後宮，位號視公、卿、大夫、元士者凡百二十人。", literal: "he established the rear palace, with ranks and titles mirroring duke, minister, grandee, and primary scholar—in all one hundred twenty persons.", idiomatic: "he established the rear palace with ranks mirroring those of duke, minister, grandee, and primary scholar—one hundred twenty women in all." },
  { zh: "莽赦天下，詔：「王匡、哀章等討青、徐盜賊，嚴尤、陳茂等討前隊丑虜，明告以生活、丹青之信。", literal: "Mang amnestied the realm and decreed: \"Wang Kuang, Ai Zhang, and others shall chastise the bandits of Qing and Xu; Yan You, Chen Mao, and others shall chastise the vanguard's ugly barbarians—clearly announcing pledges of life and sworn sincerity.\"", idiomatic: "Wang Mang proclaimed a general amnesty and decreed, \"Wang Kuang, Ai Zhang, and others shall suppress the bandits of Qing and Xu; Yan You, Chen Mao, and others shall suppress the vanguard rebels—let them be plainly assured of life and good faith.\"" },
  { zh: "復迷惑不解散，將遣大司空、隆新公將百萬之師劋絕之矣。", literal: "If they again are deluded and do not disband and scatter, I shall send the Grand Minister of Works, the Duke Who Establishes the New, to lead an army of a million to exterminate them utterly.\"", idiomatic: "If they remain deluded and refuse to disband, I shall send the Grand Minister of Works, the Duke Who Establishes the New, at the head of a million men to exterminate them utterly.\"" },
  { zh: "三月，王鳳與太常偏將軍劉秀等徇昆陽、定陵、郾，皆下之。", literal: "In the third month, Wang Feng together with Partial General of the Grand Ceremonial Liu Xiu and others marched against Kunyang, Dingling, and Yan—all submitted.", idiomatic: "In the third month, Wang Feng and Partial General of the Grand Ceremonial Liu Xiu marched on Kunyang, Dingling, and Yan—all fell." },
  { zh: "王莽聞嚴尤、陳茂敗，乃遣司空王邑馳傳，與司徒王尋發兵平定山東。", literal: "Wang Mang heard that Yan You and Chen Mao had been defeated; he thereupon sent Minister of Works Wang Yi by urgent relay, and together with Minister of Education Wang Xun mobilized troops to pacify the lands east of the mountains.", idiomatic: "Hearing of Yan You and Chen Mao's defeat, Wang Mang sent Minister of Works Wang Yi by urgent relay and, with Minister of Education Wang Xun, mobilized troops to pacify the east." },
  { zh: "征諸明兵法六十三家以備軍吏，以長人巨母霸為壘尉，又驅諸猛獸虎、豹、犀、象之屬以助威武。", literal: "He summoned sixty-three masters of military law to serve as army officers, appointed the giantess Ju Mu Ba as Rampart Commandant, and again drove all manner of fierce beasts—tigers, leopards, rhinoceroses, elephants—to aid his majesty and might.", idiomatic: "He summoned sixty-three experts in military strategy to serve as staff officers, appointed the giantess Ju Mu Ba as Rampart Commandant, and drove tigers, leopards, rhinoceroses, elephants, and other beasts to lend terror to his host." },
  { zh: "邑至洛陽，州郡各選精兵，牧守自將，定會者四十二萬人，號百萬；", literal: "When Yi reached Luoyang, each province and commandery selected crack troops; governors and administrators led them in person; those fixed to assemble numbered four hundred twenty thousand, styled a million;", idiomatic: "When Wang Yi reached Luoyang, each province and commandery sent picked troops under its governor or administrator; those assembled numbered four hundred twenty thousand, called a million;" },
  { zh: "餘在道者，旌旗、輜重，千里不絕。", literal: "the rest still on the road—with banners and baggage trains, for a thousand li without break.", idiomatic: "those still on the road stretched banners and baggage trains along the roads for a thousand li without end." },
  { zh: "夏，五月，尋、邑南出穎川，與嚴尤、陳茂合。", literal: "In summer, the fifth month, Xun and Yi marched south out of Yingchuan and joined Yan You and Chen Mao.", idiomatic: "In summer, in the fifth month, Wang Xun and Wang Yi marched south from Yingchuan and joined Yan You and Chen Mao." },
  { zh: "諸將見尋、邑兵盛，皆反走，入昆陽，惶怖，憂念妻孥，欲散歸諸城。", literal: "The generals, seeing Xun and Yi's troops vast, all turned and fled into Kunyang, fearful, brooding on wives and children, wishing to scatter and return to their various cities.", idiomatic: "The generals, seeing how vast Wang Xun and Wang Yi's army was, fled into Kunyang in panic, brooding on wives and children, ready to scatter each to his own city." },
  { zh: "劉秀曰：「今兵谷既少而外寇強大，並力御之，功庶可立；", literal: "Liu Xiu said: \"Now arms and grain are already few while the outer foe is strong and great—join strength to resist him, and merit may yet be achieved;", idiomatic: "Liu Xiu said, \"Our arms and grain are few and the enemy is strong—if we join forces we may yet prevail;" },
  { zh: "如欲分散，勢無俱全。", literal: "if you wish to scatter, in the situation none will be preserved whole.\"", idiomatic: "if we scatter, none of us will survive.\"" },
  { zh: "且宛城未拔，不能相救；", literal: "Moreover Wan city is not yet taken—we cannot rescue one another;", idiomatic: "Wan is not yet taken—we cannot rescue one another;" },
  { zh: "昆陽即拔，一日之間，諸部亦滅矣。", literal: "if Kunyang is taken, within a single day all our divisions will likewise perish.\"", idiomatic: "and if Kunyang falls, every division will be destroyed in a day.\"" },
  { zh: "今不同心膽，共舉功名，反欲守妻子財物邪！", literal: "Now you will not join heart and courage to raise merit and fame together, yet turn back wishing to guard wives, children, and goods!\"", idiomatic: "Will you not join heart and courage to win glory together, yet cling to wives, children, and goods?\"" },
  { zh: "」諸將怒曰：「劉將軍何敢如是！", literal: "\" The generals angrily said: \"General Liu, how dare you speak thus!\"", idiomatic: "\" The generals snapped, \"General Liu, how dare you speak so!\"" },
  { zh: "」秀笑而起。", literal: "\" Xiu smiled and rose.", idiomatic: "\" Liu Xiu smiled and rose." },
  { zh: "會候騎還，言：「大兵且至城北，軍陳數百里，不見其後。", literal: "Just then the scout riders returned, saying: \"The great army is about to reach the north of the city; their battle lines extend for several hundred li—you cannot see the rear.\"", idiomatic: "Just then scouts returned, reporting, \"The main host is nearly at the north wall; their battle lines stretch for hundreds of li with no end in sight.\"" },
  { zh: "」諸將素輕秀，及迫急，乃相謂曰：「更請劉將軍計之。", literal: "\" The generals had always looked down on Xiu; pressed hard now, they said to one another: \"Again ask General Liu to plan for us.\"", idiomatic: "\" The generals had always underestimated Liu Xiu; now, in extremity, they said to one another, \"Let us ask General Liu again.\"" },
  { zh: "」秀復為圖畫成敗，諸將皆曰：「諾。", literal: "\" Xiu again laid out victory and defeat for them; the generals all said: \"Agreed.\"", idiomatic: "\" Liu Xiu mapped out victory and defeat once more; the generals all said, \"Agreed.\"" },
  { zh: "」時城中唯有八九千人，秀使王鳳與廷尉大將軍王常守昆陽，夜與五威將軍李軼等十三騎出城南門，於外收兵。", literal: "\" At that time within the city there were only eight or nine thousand men; Xiu sent Wang Feng and Commandant of Justice Grand General Wang Chang to hold Kunyang, and at night with Five-Power General Li Yi and twelve other riders—thirteen in all—went out the south gate to gather troops outside.", idiomatic: "\" Only eight or nine thousand men remained in the city. Liu Xiu left Wang Feng and Commandant of Justice Grand General Wang Chang to hold Kunyang and rode out at night through the south gate with Five-Power General Li Yi and twelve others—thirteen riders in all—to gather forces outside." },
  { zh: "時莽兵到城下者且十萬，秀等幾不得出。", literal: "At that time Mang's troops reaching below the city were nearly a hundred thousand; Xiu and the others barely got out.", idiomatic: "Wang Mang's troops below the walls already neared a hundred thousand; Liu Xiu and his party barely escaped." },
  { zh: "尋、邑縱兵圍昆陽，嚴尤說邑曰：「昆陽城小而堅，今假號者在宛，亟進大兵，彼必奔走。", literal: "Xun and Yi loosed their troops to besiege Kunyang; Yan You urged Yi: \"Kunyang is small but firm; the false claimant is at Wan—hurry the great army forward and they will surely flee.\"", idiomatic: "Wang Xun and Wang Yi invested Kunyang. Yan You urged Wang Yi, \"Kunyang is small but strong, and the pretender sits at Wan. Press the main force forward and they will flee.\"" },
  { zh: "宛敗，昆陽自服。", literal: "When Wan falls, Kunyang will submit of itself.\"", idiomatic: "When Wan falls, Kunyang will submit of itself.\"" },
  { zh: "」邑曰：「吾昔圍翟義，坐不生得以見責讓。", literal: "\" Yi said: \"I once besieged Zhai Yi and was blamed for not taking him alive.\"", idiomatic: "\" Wang Yi said, \"When I besieged Zhai Yi I was blamed for failing to take him alive.\"" },
  { zh: "今將百萬之眾，遇城而不能下，非所以示威也。", literal: "Now leading a host of a million, to meet a city and not take it down is not the way to display awesomeness.\"", idiomatic: "Now at the head of a million men, to fail before a single city is no way to display power.\"" },
  { zh: "當先屠此城，蹀血而進，前歌後舞，顧不快邪！", literal: "We ought first to slaughter this city, trample blood and advance—singing before, dancing behind—would that not be joyous!\"", idiomatic: "We should slaughter this city first, trample through the blood, and march on singing and dancing—would that not be glorious?\"" },
  { zh: "」遂圍之數十重，列營百數，鉦鼓之聲聞數十里，或為地道、沖輣撞城；", literal: "\" Thereupon they besieged it in dozens of rings, arrayed hundreds of camps; the sound of gongs and drums was heard for several tens of li; some dug tunnels, others rammed the walls with assault carts;", idiomatic: "\" They invested the city in layer upon layer, pitched hundreds of camps, and set gongs and drums roaring for tens of li; some dug tunnels, others battered the walls with siege engines;" },
  { zh: "積弩亂髮，矢下如雨，城中負戶而汲。", literal: "massed crossbows fired in disorder; arrows fell like rain; within the city men drew water braced against their doors.", idiomatic: "massed crossbows volleyed without cease; arrows fell like rain; inside the city men drew water braced against their doors." },
  { zh: "王鳳等乞降，不許。", literal: "Wang Feng and others begged to surrender; it was not permitted.", idiomatic: "Wang Feng and the others begged to surrender; Wang Yi refused." },
  { zh: "尋、邑自以為功在漏刻，不以軍事為憂。", literal: "Xun and Yi deemed their achievement within the dripping clepsydra and did not take military affairs as a worry.", idiomatic: "Wang Xun and Wang Yi thought victory was only a matter of moments and took no thought for the fighting." },
  { zh: "嚴尤曰：「《兵法》：『圍城為之闕』，宜使得逸出以怖宛下。", literal: "Yan You said: \"The Art of War: 'When besieging a city, leave it a gap'—it is fitting to let them escape to terrify those below Wan.\"", idiomatic: "Yan You said, \"The Art of War says, 'When you besiege a city, leave a gap.' Let them escape to terrify the defenders of Wan.\"" },
  { zh: "」邑又不聽。", literal: "\" Yi again would not listen.", idiomatic: "\" Wang Yi would not listen." },
  { zh: "棘陽守長岑彭與前隊貳嚴說共守宛城，漢兵攻之數月，城中人相食，乃舉城降。", literal: "Jiyang Defender Chief Cen Peng together with Vanguard Deputy Yan Shuo jointly held Wan city; Han troops attacked for months; within the city men ate one another; thereupon they surrendered the whole city.", idiomatic: "Jiyang Defender Chief Cen Peng and Vanguard Deputy Yan Shuo held Wan; Han forces besieged it for months until the people ate one another, then surrendered the city." },
  { zh: "更始入都之。", literal: "Gengshi entered and made it his capital.", idiomatic: "The Gengshi Emperor entered and made it his capital." },
  { zh: "諸將欲殺彭，劉縯曰：「彭，郡之大吏，執心堅守，是其節也。", literal: "The generals wished to kill Peng; Liu Yan said: \"Peng is a great officer of the commandery; he held his heart firm in defense—that is his integrity.\"", idiomatic: "The generals wished to execute Cen Peng. Liu Yan said, \"Peng is a senior commandery officer who held firm—that is integrity.\"" },
  { zh: "今舉大事，當表義士，不如封之。", literal: "Now that we undertake a great affair, we ought to honor men of righteousness—better to enfeoff him.\"", idiomatic: "Now that we undertake a great enterprise, we ought to honor men of righteousness. Better to enfeoff him.\"" },
  { zh: "」更始乃封彭為歸德侯。", literal: "\" Gengshi thereupon enfeoffed Peng as Marquis Who Returns to Virtue.", idiomatic: "\" The Gengshi Emperor enfeoffed Cen Peng as Marquis Who Returns to Virtue." },
  { zh: "劉秀至郾、定陵，悉發諸營兵。", literal: "Liu Xiu reached Yan and Dingling and mustered all the camp troops.", idiomatic: "Liu Xiu reached Yan and Dingling and mustered every camp." },
  { zh: "諸將貪惜財物，欲分兵守之。", literal: "The generals, greedy and cherishing goods, wished to divide troops to guard them.", idiomatic: "The generals, greedy for loot, wished to detach men to guard it." },
  { zh: "秀曰：「今若破敵，珍寶萬倍，大功可成；", literal: "Xiu said: \"If now we break the enemy, treasures will be ten thousandfold and great merit can be achieved;", idiomatic: "Liu Xiu said, \"If we break the enemy now, treasure will be ours ten thousandfold and great merit won;" },
  { zh: "如為所敗，首領無餘，何財物之有！", literal: "if we are defeated by them, heads and necks will not remain—what goods could there be!\"", idiomatic: "if we are defeated, we will not keep our heads—what goods will matter then?\"" },
  { zh: "」乃悉發之。", literal: "\" He thereupon mustered them all.", idiomatic: "\" He mustered them all." },
  { zh: "六月，己卯朔，秀與諸營俱進，自將步騎千餘為前鋒，去大軍四五里而陳；", literal: "In the sixth month, on the new moon of jimao, Xiu advanced with all camps together, himself leading a thousand-odd infantry and cavalry as vanguard, deploying four or five li from the great army;", idiomatic: "In the sixth month, on the new moon of jimao, Liu Xiu advanced with every camp, himself leading a thousand infantry and cavalry as vanguard, drawn up four or five li ahead of the main body;" },
  { zh: "尋、邑亦遣兵數千合成，秀奔之，斬首數十級。", literal: "Xun and Yi also sent several thousand men to engage; Xiu charged them and beheaded several tens.", idiomatic: "Wang Xun and Wang Yi sent several thousand men to meet him; Liu Xiu charged and took several dozen heads." },
  { zh: "諸將喜曰：「劉將軍平生見小敵怯，今見大敵勇，甚可怪也！", literal: "The generals rejoiced and said: \"General Liu in ordinary times sees small foes and is timid; now seeing a great foe he is brave—very strange indeed!\"", idiomatic: "The generals exclaimed, \"General Liu has always been timid before small foes—now before a great army he is bold. How strange!\"" },
  { zh: "且復居前，請助將軍！", literal: "Again take the fore—we beg to aid the general!\"", idiomatic: "Lead on again—we beg to fight beside you!\"" },
  { zh: "」秀復進，尋、邑兵卻，諸部共乘之，斬首數百千級。", literal: "\" Xiu advanced again; Xun and Yi's troops gave way; all divisions together pressed the advantage and beheaded several hundred to a thousand heads.", idiomatic: "\" Liu Xiu pressed forward again; Wang Xun and Wang Yi's line gave way; every division joined the pursuit and took hundreds and thousands of heads." },
  { zh: "連勝，遂前，諸將膽氣益壯，無不一當百，秀乃與敢死者三千人從城西水上衝其中堅。", literal: "Victory followed victory; they pressed forward; the generals' courage grew ever bolder—none but fought one against a hundred; Xiu then with three thousand dare-to-die men from west of the city along the water struck the enemy's core.", idiomatic: "Victory followed victory as they pressed on; the generals' courage swelled until each fought as ten; Liu Xiu then led three thousand dare-to-die men from the west along the river and struck the enemy's core." },
  { zh: "尋、邑易之，自將萬餘人行陳，敕諸營皆按部毋得動，獨迎與漢兵戰，不利，大軍不敢擅相救。", literal: "Xun and Yi held it lightly; Yi himself led ten thousand-odd men into the lines, ordering all camps to hold their posts and not move—he alone went to meet Han troops in battle; it went ill; the great army dared not on its own rescue one another.", idiomatic: "Wang Xun and Wang Yi took it lightly; Wang Yi personally led ten thousand men into the line, ordering every camp to hold position and not move, and met the Han force alone. The fight went ill; the main host dared not rescue him without orders." },
  { zh: "尋、邑陳亂，漢兵乘銳崩之，遂殺王尋。", literal: "Xun and Yi's battle lines fell into disorder; Han troops, riding their sharp momentum, broke them and thereupon killed Wang Xun.", idiomatic: "Wang Xun and Wang Yi's formation collapsed; the Han troops pressed their advantage and killed Wang Xun." },
  { zh: "城中亦鼓噪而出，中外合勢，震呼動天地。", literal: "Within the city they also drummed and shouted and came out; inner and outer joined force; thunderous cries shook heaven and earth.", idiomatic: "Inside the city drums roared and the garrison poured out; inner and outer forces joined; their shouts shook heaven and earth." },
  { zh: "莽兵大潰，走者相騰踐，伏屍百餘里。", literal: "Mang's troops broke utterly; those who fled trampled one another; corpses lay prone for more than a hundred li.", idiomatic: "Wang Mang's army broke utterly; fugitives trampled one another; corpses littered the ground for more than a hundred li." },
  { zh: "會大雷、風、屋瓦皆飛，雨下如注，滍川盛溢，虎豹皆股戰，士卒赴水溺死者以萬數，水為不流。", literal: "Just then great thunder and wind came; roof tiles all flew; rain poured like poured water; the Zhi River swelled and overflowed; even tigers and leopards trembled in the thighs; soldiers who rushed into the water and drowned numbered in the tens of thousands—the water would not flow.", idiomatic: "Thunder and wind rose; roof tiles flew; rain poured in torrents; the Zhi River swelled until tigers and leopards trembled; tens of thousands of soldiers drowned in the flood and the water itself ceased to flow." },
  { zh: "王邑、嚴尤、陳茂輕騎乘死人度水逃去，盡獲其軍實輜重，不可勝算，舉之連月不盡，或燔燒其餘。", literal: "Wang Yi, Yan You, and Chen Mao on light horses rode atop the dead to cross the water and escape; they captured all their army stores and baggage beyond reckoning—lifting them took months without end; some burned the remainder.", idiomatic: "Wang Yi, Yan You, and Chen Mao fled on light horses, using corpses to cross the water; the victors seized baggage and stores beyond counting—months of hauling could not carry it all, and much was burned." },
  { zh: "士卒奔走，各還其郡，王邑獨與所將長安勇敢數千人還洛陽，關中聞之震恐。", literal: "Soldiers fled, each returning to his commandery; Wang Yi alone with the several thousand Chang'an braves he led returned to Luoyang; within the passes, hearing of it, all trembled in terror.", idiomatic: "Soldiers scattered to their home commanderies; only Wang Yi led several thousand Chang'an veterans back to Luoyang; within the passes, the news spread terror." },
  { zh: "於是海內豪桀翕然響應，皆殺其牧守，自稱將軍，用漢年號以待詔命。", literal: "Thereupon heroes throughout the realm responded as one; all killed their governors and administrators, styled themselves generals, and used Han era names while awaiting imperial orders.", idiomatic: "Heroes throughout the realm rose as one, killed their governors and administrators, styled themselves generals, and adopted Han era names while awaiting the throne's command." },
  { zh: "旬月之間，遍於天下。", literal: "Within a month or so, it spread across the realm.", idiomatic: "Within a month it spread across the empire." },
  { zh: "莽聞漢兵言莽鴆殺孝平皇帝，乃會公卿於王路堂，開所為平帝請命金縢之策，泣以示群臣。", literal: "Mang heard Han troops say Mang had poisoned Emperor Xiaoping; he thereupon assembled dukes and ministers in the Hall of the King's Way, opened the golden casket petition he had made for Emperor Ping's life, and weeping showed it to the host of ministers.", idiomatic: "Hearing Han troops claim he had poisoned Emperor Xiaoping, Wang Mang assembled the court in the Hall of the King's Way, opened the golden-casket petition he had written for Emperor Ping's recovery, and weeping showed it to his ministers." },
  { zh: "劉秀復徇穎川，攻父城不下，屯兵巾車鄉。", literal: "Liu Xiu again marched through Yingchuan, attacked Fucheng but could not take it, and encamped his troops at Jinche village.", idiomatic: "Liu Xiu marched again through Yingchuan, besieged Fucheng without success, and encamped at Jinche village." },
  { zh: "穎川郡掾馮異監五縣，為漢兵所獲。", literal: "Yingchuan Commandery Assistant Feng Yi oversaw five counties and was captured by Han troops.", idiomatic: "Yingchuan Commandery Assistant Feng Yi, who oversaw five counties, was captured by Han forces." },
  { zh: "異曰：「異有老母在父城，願歸，據五城以效功報德！", literal: "Yi said: \"Yi has an old mother in Fucheng; I wish to return and hold the five cities to repay merit with service and return virtue with deeds!\"", idiomatic: "Feng Yi said, \"My old mother is in Fucheng. Let me return and hold the five cities to repay your kindness with service!\"" },
  { zh: "」秀許之。", literal: "\" Xiu permitted it.", idiomatic: "\" Liu Xiu agreed." },
  { zh: "異歸，謂父城長苗萌曰：「諸將多暴橫，獨劉將軍所到不虜略，觀其言語舉止，非庸人也。", literal: "Yi returned and said to Fucheng Magistrate Miao Meng: \"Most generals are violent and overbearing; only General Liu, wherever he goes, does not plunder. Watch his words and bearing—he is no ordinary man.\"", idiomatic: "Feng Yi returned and told Fucheng Magistrate Miao Meng, \"Most generals are brutal, but General Liu does not plunder where he goes. Mark his speech and bearing—he is no ordinary man.\"" },
  { zh: "」遂與萌率五縣以降。", literal: "\" Thereupon together with Meng he led the five counties to surrender.", idiomatic: "\" He and Miao Meng then led the five counties to surrender." },
  { zh: "新市、平林諸將以劉縯兄弟威名益盛，陰勸更始除之。", literal: "The Xinshi and Pinglin generals, because the renown of Liu Yan and his brothers grew daily greater, secretly urged Gengshi to remove them.", idiomatic: "The Xinshi and Pinglin generals, seeing Liu Yan and his brothers grow ever more formidable, secretly urged the Gengshi Emperor to eliminate them." },
  { zh: "秀謂縯曰：「事欲不善。", literal: "Xiu said to Yan: \"Affairs are about to go ill.\"", idiomatic: "Liu Xiu told Liu Yan, \"Matters are turning dangerous.\"" },
  { zh: "」縯笑曰：「常如是耳。", literal: "\" Yan laughed and said: \"It is always thus.\"", idiomatic: "\" Liu Yan laughed and said, \"It is always thus.\"" },
  { zh: "」更始大會諸將，取縯寶劍視之。", literal: "\" Gengshi held a great assembly of generals and took Yan's treasured sword to examine it.", idiomatic: "\" The Gengshi Emperor held a great assembly of generals and took Liu Yan's treasured sword to examine it." },
  { zh: "繡衣御史申徒建隨獻玉玦，更始不敢發。", literal: "Embroidered-cloak Censor Shentu Jian followed by presenting a jade disk; Gengshi dared not act.", idiomatic: "Embroidered-cloak Censor Shentu Jian followed by offering a jade disk; the emperor dared not act." },
  { zh: "縯舅樊宏謂縯曰：「建得無有范增之意乎？", literal: "Yan's uncle Fan Hong said to Yan: \"Does Jian perhaps have the intent of Fan Zeng?\"", idiomatic: "Liu Yan's uncle Fan Hong said to him, \"Does Jian mean what Fan Zeng meant?\"" },
  { zh: "」縯不應。", literal: "\" Yan did not answer.", idiomatic: "\" Liu Yan did not answer." },
  { zh: "李軼初與縯兄弟善，後更諂事新貴。", literal: "Li Yi at first was on good terms with Yan and his brothers; later he turned to fawn on the newly risen.", idiomatic: "Li Yi had once been close to the Yan brothers; later he turned to fawn on the new powers." },
  { zh: "秀戒縯曰：「此人不可覆信。", literal: "Xiu warned Yan: \"This man cannot be trusted again.\"", idiomatic: "Liu Xiu warned Liu Yan, \"This man cannot be trusted again.\"" },
  { zh: "」縯不從。", literal: "\" Yan did not follow him.", idiomatic: "\" Liu Yan did not listen." },
  { zh: "縯部將劉稷，勇冠三軍，聞更始立，怒曰：「本起兵圖大事者，伯升兄弟也。", literal: "Yan's division general Liu Ji, whose courage topped the three armies, hearing Gengshi had been set up, angrily said: \"Those who originally raised troops to achieve the great affair were Bo Sheng and his brothers.\"", idiomatic: "Liu Yan's officer Liu Ji, bravest in the army, hearing of the enthronement, raged, \"It was Bo Sheng and his brothers who first raised arms for the great enterprise.\"" },
  { zh: "今更始何為者邪！", literal: "What is this Gengshi creature!\"", idiomatic: "What is this Gengshi creature doing on the throne?\"" },
  { zh: "」更始以稷為抗威將軍，稷不肯拜。", literal: "\" Gengshi made Ji Resist-Authority General; Ji refused to accept the appointment.", idiomatic: "\" The Gengshi Emperor made Liu Ji Resist-Authority General; Ji refused to accept the appointment." },
  { zh: "更始乃與諸將陳兵數千人，先收稷，將誅之，縯固爭。", literal: "Gengshi then with the generals arrayed several thousand troops, first seized Ji, and was about to execute him; Yan firmly remonstrated.", idiomatic: "The Gengshi Emperor then arrayed several thousand troops with his generals, first seized Ji, and was about to execute him; Liu Yan firmly remonstrated." },
  { zh: "李軼、朱鮪因勸更始並執縯，即日殺之。", literal: "Li Yi and Zhu Wei thereupon urged Gengshi to seize Yan as well, and that same day killed him.", idiomatic: "Li Yi and Zhu Wei thereupon urged the Gengshi Emperor to seize Yan as well, and killed him that same day." },
  { zh: "以族兄光祿勳賜為大司徒。", literal: "His clansman elder brother Director of the Masters of Writing Ci was made Grand Master of Works.", idiomatic: "He made his clansman Liu Ci, Director of the Masters of Writing, Grand Master of Works." },
  { zh: "秀聞之，自父城馳詣宛謝。", literal: "Xiu heard of it and from Fucheng galloped to Wan to apologize.", idiomatic: "Liu Xiu heard of it and galloped from Fucheng to Wan to apologize." },
  { zh: "司徒官屬迎吊秀，秀不與交私語，惟深引過而已，未嘗自伐昆陽之功；", literal: "The Grand Master of Works' staff came to welcome and mourn Xiu; Xiu did not exchange private words with them, only deeply acknowledged fault—that was all—and never boasted of his Kunyang achievement;", idiomatic: "The Grand Master of Works' staff came to welcome and console Liu Xiu; Xiu would not speak with them privately, only deeply acknowledged his own fault, and never boasted of his Kunyang victory;" },
  { zh: "又不敢為縯服喪，飲食言笑如平常。", literal: "nor dared to wear mourning for Yan; eating, drinking, speech, and laughter were as in ordinary times.", idiomatic: "nor dared to wear mourning for Liu Yan; he ate, drank, spoke, and laughed as usual." },
  { zh: "更始以是慚，拜秀為破虜大將軍，封武信侯。", literal: "Gengshi was thereby ashamed and appointed Xiu General Who Breaks Bandits, enfeoffing him as Marquis of Martial Faith.", idiomatic: "The Gengshi Emperor was thereby ashamed and appointed Liu Xiu General Who Breaks Bandits, enfeoffing him as Marquis of Martial Faith." },
  { zh: "道士西門君惠謂王莽衛將軍王涉曰：「讖文劉氏當復興，國師公姓名是也。", literal: "The Daoist Xi Men Junhui said to Wang Mang's Guard General Wang She: \"The prophecy-text says the Liu house is to revive—the National Preceptor's name and surname are just that.", idiomatic: "The Daoist Xi Men Junhui said to Wang Mang's Guard General Wang She: \"The prophecy-text says the Liu house is to revive—the National Preceptor's name and surname fit exactly." },
  { zh: "」涉遂與國師公劉秀、大司馬董忠、司中大贅孫人及謀以所部兵劫莽降漢，以全宗族。", literal: "\" She thereupon with National Preceptor Liu Xiu, Grand Marshal Dong Zhong, Director of the Center Great Assistant Sun Ren, and others plotted to use their troops to seize Mang and surrender to Han, thereby to preserve their clans.", idiomatic: "\" She thereupon plotted with National Preceptor Liu Xiu, Grand Marshal Dong Zhong, Director of the Center Great Assistant Sun Ren, and others to use their troops to seize Wang Mang and surrender to Han and thereby preserve their clans." },
  { zh: "秋，七月，人及以其謀告莽，莽召忠詰責，因格殺之，使虎賁以斬馬劍剉忠，收其宗族，以醇醯、毒藥、白刃、叢棘並一坎而埋之；", literal: "In autumn, the seventh month, Ren and others reported their plot to Mang; Mang summoned Zhong to interrogate and blame him, and on the spot killed him, had the tiger guards dismember Zhong with the horse-slaying sword, seized his clan, and buried them together in one pit with strong vinegar, poison, bare blades, and thorn thickets;", idiomatic: "In autumn, the seventh month, Ren and others reported the plot to Wang Mang; Mang summoned Dong Zhong to interrogate him, killed him on the spot, had the tiger guards dismember him with the horse-slaying sword, seized his clan, and buried them together in one pit with strong vinegar, poison, bare blades, and thorn thickets;" },
  { zh: "秀、涉皆自殺。", literal: "Xiu and She both killed themselves.", idiomatic: "Liu Xiu and Wang She both killed themselves." },
  { zh: "莽以其骨肉、舊臣，惡其內潰，故隱其誅。", literal: "Because they were his kin and old ministers, Mang hated that the inner circle had split, and therefore concealed their executions.", idiomatic: "Because they were his kin and old ministers, Wang Mang hated that the inner circle had split and therefore concealed their executions." },
  { zh: "莽以軍師外破，大臣內畔，左右亡所信，不能復遠念郡國，乃召王邑還，為大司馬，以大長秋張邯為大司徒，崔發為大司空，司中壽容苗訢為國師。", literal: "Mang, with strategists defeated without and great ministers rebelling within, having no one left to trust at his side, could no longer think far of commanderies and states; he recalled Wang Yi, made him Grand Marshal, made Grand Chamberlain Zhang Han Grand Master of Works, Cui Fa Grand Minister of Works, and Director of the Center Shou Rong Miao Xin National Preceptor.", idiomatic: "With strategists defeated abroad and great ministers rebelling within, Wang Mang had no one left to trust at his side and could no longer attend to distant commanderies; he recalled Wang Yi as Grand Marshal, made Grand Chamberlain Zhang Han Grand Master of Works, Cui Fa Grand Minister of Works, and Director of the Center Shou Rong Miao Xin National Preceptor." },
  { zh: "莽憂懣不能食，但飲酒，啖鰒魚；", literal: "Mang was distressed and vexed and could not eat, only drinking wine and eating abalone;", idiomatic: "Wang Mang was distressed and could not eat, drinking only wine and eating abalone;" },
  { zh: "讀軍書倦，因馮幾寐，不復就枕矣。", literal: "reading military documents until weary, he then leaned on the armrest and slept, no longer going to his pillow.", idiomatic: "when weary of reading military documents he would lean on his armrest and sleep, no longer going to his pillow." },
  { zh: "成紀隗崔、隗義、上邽楊廣、冀人周宗同起兵以應漢，眾數千人，攻平襄，殺莽鎮戎大尹李育。", literal: "Chengji's Wei Cui and Wei Yi, Shanggui's Yang Guang, and Zhou Zong of Ji together raised troops in response to Han, their host several thousand men; they attacked Pingxiang and killed Mang's Grand Administrator of Pacifying the Rong Li Yu.", idiomatic: "Wei Cui and Wei Yi of Chengji, Yang Guang of Shanggui, and Zhou Zong of Ji together raised troops in response to Han with a force of several thousand, attacked Pingxiang, and killed Wang Mang's Grand Administrator of Pacifying the Rong Li Yu." },
  { zh: "崔兄子囂，素有名，好經書，崔等共推為上將軍。", literal: "Cui's elder brother's son Ao had long had a name and loved the classics; Cui and the others together pushed him as supreme general.", idiomatic: "Cui's nephew Ao had long been renowned and loved the classics; Cui and the others together made him supreme general." },
  { zh: "崔為白虎將軍，義為左將軍。", literal: "Cui was made White Tiger General and Yi Left General.", idiomatic: "Cui was made White Tiger General and Yi Left General." },
  { zh: "囂遣使聘平陵方望，以為軍師。", literal: "Ao sent envoys to engage Fang Wang of Pingling and made him army strategist.", idiomatic: "Ao sent envoys to engage Fang Wang of Pingling as army strategist." },
  { zh: "望說囂立高廟於邑東。", literal: "Wang urged Ao to establish the High Temple east of the town.", idiomatic: "Wang urged Ao to establish the High Temple east of the town." },
  { zh: "己巳，祀高祖、太宗、世宗，囂等皆稱臣執事，殺馬同盟，以興輔劉宗；", literal: "On the day jisi they sacrificed to Gaozu, Taizong, and Shizong; Ao and the others all styled themselves subjects performing rites, killed a horse and allied by oath to revive and assist the Liu house;", idiomatic: "On the day jisi they sacrificed to Gaozu, Taizong, and Shizong; Ao and the others all styled themselves subjects, killed a horse and swore alliance to revive and assist the house of Liu;" },
  { zh: "移檄郡國，數莽罪惡。", literal: "they issued a proclamation to commanderies and states enumerating Mang's crimes and evils.", idiomatic: "they issued a proclamation to commanderies and states enumerating Wang Mang's crimes." },
  { zh: "勒兵十萬，擊殺雍州牧陳慶、安定大尹王向。", literal: "They mustered a hundred thousand troops and attacked and killed Governor of Yongzhou Chen Qing and Grand Administrator of Anding Wang Xiang.", idiomatic: "They mustered a hundred thousand troops and killed Governor of Yongzhou Chen Qing and Grand Administrator of Anding Wang Xiang." },
  { zh: "分遣諸將徇隴西、武都、金城、武威、張掖、酒泉、敦煌，皆下之。", literal: "They sent out the various generals to overrun Longxi, Wudu, Jincheng, Wuwei, Zhangye, Jiuquan, and Dunhuang—all were taken.", idiomatic: "They sent out generals to overrun Longxi, Wudu, Jincheng, Wuwei, Zhangye, Jiuquan, and Dunhuang, and all submitted." },
  { zh: "初，茂陵公孫述為清水長，有能名；", literal: "Earlier, Maoling's Gongsun Shu was magistrate of Qingshui and had a reputation for ability;", idiomatic: "Earlier, Gongsun Shu of Maoling had been magistrate of Qingshui and enjoyed a reputation for ability;" },
  { zh: "遷導江卒正，治臨邛。", literal: "he was transferred to Guide-the-River colonel and governed Linqiong.", idiomatic: "he was transferred to Guide-the-River colonel and governed Linqiong." },
  { zh: "漢兵起，南陽宗成、商人王岑起兵徇漢中以應漢，殺王莽庸部牧宋遵，眾合數萬人。", literal: "When Han troops rose, Nanyang's Zong Cheng and the merchant Wang Cen raised troops and overran Hanzhong in response to Han, killed Wang Mang's Governor of Yong Song Zun, and their hosts together numbered tens of thousands.", idiomatic: "When Han forces rose, Zong Cheng of Nanyang and the merchant Wang Cen raised troops, overran Hanzhong in response to Han, killed Wang Mang's Governor of Yong Song Zun, and together mustered tens of thousands." },
  { zh: "述遣使迎成等，成等至成都，虜掠暴橫。", literal: "Shu sent envoys to welcome Cheng and the others; when Cheng and the others reached Chengdu they plundered and were violent and overbearing.", idiomatic: "Shu sent envoys to welcome them; when Cheng and the others reached Chengdu they plundered violently." },
  { zh: "述召群中豪桀謂曰：「天下同苦新室，思劉氏久矣，故聞漢將軍到，馳迎道路。", literal: "Shu summoned the local powerful men and said: \"All under heaven alike suffer under the New House and have long yearned for the Liu; therefore when they heard Han generals had come they raced to welcome them on the roads.", idiomatic: "Shu summoned the local powerful men and said: \"All under heaven alike suffer under the New House and have long yearned for the Liu; therefore when they heard Han generals had arrived they raced to welcome them on the roads." },
  { zh: "今百姓無辜而婦子係獲，此寇賊，非義兵也。", literal: "Now the common people are innocent yet wives and children are bound and captured—this is banditry, not righteous troops.", idiomatic: "Now innocent common people have their wives and children bound and captured—this is banditry, not righteous troops." },
  { zh: "」乃使人詐稱漢使者，假述輔漢將軍、蜀郡太守兼益州牧印綬；", literal: "\" He then had someone falsely claim to be a Han envoy and lend Shu the seals and cords of Assistant-to-Han General, Administrator of Shu commandery, and concurrent Governor of Yizhou;", idiomatic: "\" He then had someone falsely claim to be a Han envoy and lend Shu the seals and cords of Assistant-to-Han General, Administrator of Shu, and concurrent Governor of Yizhou;" },
  { zh: "選精兵西擊成等，殺之，並其眾。", literal: "he selected crack troops, struck west against Cheng and the others, killed them, and absorbed their hosts.", idiomatic: "he selected crack troops, struck west against Cheng and the others, killed them, and absorbed their forces." },
  { zh: "前鐘武侯劉望起兵汝南，嚴尤、陳茂往歸之；", literal: "Former Marquis of Zhongwu Liu Wang raised troops in Runan; Yan You and Chen Mao went to join him;", idiomatic: "Former Marquis of Zhongwu Liu Wang raised troops in Runan; Yan You and Chen Mao went to join him;" },
  { zh: "八月，望即帝位，以尤為大司馬，茂為丞相。", literal: "In the eighth month Wang declared himself emperor, made You Grand Marshal, and Mao Chancellor.", idiomatic: "In the eighth month Wang declared himself emperor, made Yan You Grand Marshal, and Chen Mao Chancellor." },
  { zh: "王莽使太師王匡、國將哀章守洛陽。", literal: "Wang Mang sent Grand Preceptor Wang Kuang and State General Ai Zhang to hold Luoyang.", idiomatic: "Wang Mang sent Grand Preceptor Wang Kuang and State General Ai Zhang to hold Luoyang." },
  { zh: "更始遣定國上公王匡攻洛陽，西屏大將軍申屠建、丞相司直李松攻武關，三輔震動。", literal: "Gengshi sent Stabilize-the-Realm Upper Duke Wang Kuang to attack Luoyang, and Western Screen Great General Shentu Jian and Chancellor Director of Integrity Li Song to attack Wuguan; the Three Metropolises were shaken.", idiomatic: "The Gengshi Emperor sent Stabilize-the-Realm Upper Duke Wang Kuang against Luoyang and Western Screen Great General Shentu Jian and Chancellor Director of Integrity Li Song against Wuguan; the Three Metropolises were shaken." },
  { zh: "析人鄧曄、於匡起兵南鄉以應漢，攻武關都尉朱萌，萌降；", literal: "Xi's Deng Ye and Yu Kuang raised troops in Nanxiang in response to Han, attacked Wuguan Commandant Zhu Meng, and Meng surrendered;", idiomatic: "Deng Ye of Xi and Yu Kuang raised troops in Nanxiang in response to Han, attacked Wuguan Commandant Zhu Meng, and Meng surrendered;" },
  { zh: "進攻右隊大夫宋綱，殺之；", literal: "they advanced to attack Right Column Grandee Song Gang and killed him;", idiomatic: "they advanced against Right Column Grandee Song Gang and killed him;" },
  { zh: "西拔湖。", literal: "and took Hu to the west.", idiomatic: "and took Hu to the west." },
  { zh: "莽愈憂，不知所出。", literal: "Mang grew more distressed and did not know what course to take.", idiomatic: "Wang Mang grew more distressed and did not know what to do." },
  { zh: "崔發言：「古者國有大災，則哭以厭之。", literal: "Cui Fa said: \"In antiquity when a state had a great calamity, it wept to suppress it.", idiomatic: "Cui Fa said: \"In antiquity when a state suffered a great calamity, it wept to suppress it." },
  { zh: "宜告天以求救。", literal: "One ought to announce to Heaven and seek rescue.", idiomatic: "One ought to announce to Heaven and seek rescue." },
  { zh: "」莽乃率群臣至南郊，陳其符命本末，仰天大哭，氣盡，伏而叩頭。", literal: "\" Mang then led the ministers to the southern suburb, set forth the origin and end of his talisman-mandate, looked up to Heaven and wept greatly until his breath was spent, and prostrated himself knocking his head.", idiomatic: "\" Wang Mang then led the ministers to the southern suburb, set forth the origin and end of his talisman-mandate, looked up to Heaven and wept until his breath was spent, and prostrated himself knocking his head." },
  { zh: "諸生、小民旦夕會哭，為設飧粥；", literal: "Students and common people met to weep morning and evening; gruel was provided for them;", idiomatic: "Students and common people met to weep morning and evening, and gruel was provided;" },
  { zh: "甚悲哀者，除以為郎，郎至五千餘人。", literal: "those most sorrowful were appointed gentlemen; the gentlemen reached more than five thousand.", idiomatic: "those most sorrowful were appointed gentlemen-at-court, until the gentlemen reached more than five thousand." },
  { zh: "莽拜將軍九人，皆以虎為號，將北軍精兵數萬人以東，內其妻子宮中以為質。", literal: "Mang appointed nine generals, all with tiger in their titles, to lead several tens of thousands of Northern Army crack troops eastward, and lodged their wives and children in the palace as hostages.", idiomatic: "Wang Mang appointed nine generals, all with tiger in their titles, to lead several tens of thousands of Northern Army crack troops eastward, and lodged their wives and children in the palace as hostages." },
  { zh: "時省中黃金尚六十餘萬斤，它財物稱是，莽愈愛之，賜九虎士人四千錢；", literal: "At the time the palace still had more than six hundred thousand jin of gold, and other goods in proportion; Mang loved them all the more and gave the Nine Tigers four thousand cash per soldier;", idiomatic: "At the time the palace still held more than six hundred thousand jin of gold and other goods in proportion; Wang Mang prized them all the more and gave the Nine Tigers four thousand cash per soldier;" },
  { zh: "眾重怨，無鬥意。", literal: "the troops were heavily resentful and had no will to fight.", idiomatic: "the troops were deeply resentful and had no will to fight." },
  { zh: "九虎至華陰回谿，距隘自守。", literal: "The Nine Tigers reached Huayin's Hui Gorge and held the narrow pass in self-defense.", idiomatic: "The Nine Tigers reached Huayin's Hui Gorge and held the narrow pass." },
  { zh: "於匡、鄧曄擊之，六虎敗走；", literal: "Yu Kuang and Deng Ye attacked them; six tigers were defeated and fled;", idiomatic: "Yu Kuang and Deng Ye attacked them; six tigers were defeated and fled;" },
  { zh: "二虎詣闕歸死，莽使使責死者安在，皆自殺；", literal: "two tigers came to the gate to return and die; Mang sent envoys to demand where the dead were—all killed themselves;", idiomatic: "two tigers came to the palace to surrender and die; Wang Mang sent envoys demanding where the dead were—all killed themselves;" },
  { zh: "其四虎亡。", literal: "the other four tigers fled.", idiomatic: "the other four tigers fled." },
  { zh: "三虎收散卒保渭口京師倉。", literal: "Three tigers gathered scattered troops and held the Capital Granary at the Wei mouth.", idiomatic: "Three tigers gathered scattered troops and held the Capital Granary at the Wei mouth." },
  { zh: "鄧曄開武關迎漢兵。", literal: "Deng Ye opened Wuguan to welcome Han troops.", idiomatic: "Deng Ye opened Wuguan to welcome Han troops." },
  { zh: "李松將三千餘人至湖，與曄等共攻京師倉，未下。", literal: "Li Song led more than three thousand men to Hu and with Ye and the others together attacked the Capital Granary but did not take it.", idiomatic: "Li Song led more than three thousand men to Hu and with Ye and the others attacked the Capital Granary but did not take it." },
  { zh: "曄以弘農掾王憲為校尉，將數百人北度渭，入左馮翊界。", literal: "Ye made Hongnong clerk Wang Xian colonel, leading several hundred men north across the Wei into the territory of Left Fengyi.", idiomatic: "Ye made Hongnong clerk Wang Xian colonel and led several hundred men north across the Wei into Left Fengyi." },
  { zh: "李松遣偏將軍韓臣等徑西至新豐擊破莽波水將軍，追奔至長門宮。", literal: "Li Song sent Lieutenant General Han Chen and others straight west to Xinfeng, defeated Mang's Bo-water General, and pursued the rout to Changmen Palace.", idiomatic: "Li Song sent Lieutenant General Han Chen and others straight west to Xinfeng, defeated Wang Mang's Bo-water General, and pursued the rout to Changmen Palace." },
  { zh: "王憲北至頻陽，所過迎降。", literal: "Wang Xian went north to Pinyang; wherever he passed they came out to welcome and surrender.", idiomatic: "Wang Xian went north to Pinyang; wherever he passed they welcomed and surrendered." },
  { zh: "諸縣大姓名各起兵稱漢將，率眾隨憲。", literal: "The great family names of the various counties each raised troops styling themselves Han generals and led their hosts to follow Xian.", idiomatic: "The great families of the various counties each raised troops styling themselves Han generals and led their hosts to follow Xian." },
  { zh: "李松、鄧曄引軍至華陰，而長安旁兵四會城下；", literal: "Li Song and Deng Ye led their armies to Huayin, while troops from around Chang'an on four sides converged below the city;", idiomatic: "Li Song and Deng Ye led their armies to Huayin while troops from around Chang'an converged on four sides below the city;" },
  { zh: "又聞天水隗氏方到，皆爭欲先入城，貪立大功、鹵掠之利。", literal: "and hearing the Wei clan of Tianshui was just arriving, all strove to enter the city first, greedy to establish great merit and the profit of plunder.", idiomatic: "and hearing the Wei clan of Tianshui was just arriving, all strove to enter the city first, greedy for great merit and plunder." },
  { zh: "莽赦城中囚徒，皆授兵，殺豨，飲其血，與誓曰：「有不為新室者，社鬼記之！", literal: "Mang amnestied the prisoners in the city, all were given arms; a boar was killed and they drank its blood, and he swore with them: \"Whoever is not for the New House—the community spirits will record it!", idiomatic: "Wang Mang amnestied the city's prisoners, armed them all, killed a boar, had them drink its blood, and swore: \"Whoever is not for the New House—the community spirits will record it!" },
  { zh: "」使更始將軍史諶將之。", literal: "\" He had General of Renewal Shi Chen lead them.", idiomatic: "\" He had General of Renewal Shi Chen lead them." },
  { zh: "度渭橋，皆散走；", literal: "When they crossed the Wei Bridge all scattered and fled;", idiomatic: "When they crossed the Wei Bridge all scattered and fled;" },
  { zh: "諶空還。", literal: "Chen returned empty.", idiomatic: "Chen returned empty-handed." },
  { zh: "眾兵發掘莽妻、子、父、祖塚，燒其棺槨及九廟、明堂、辟雍，火照城中。", literal: "The multitude of troops dug up the tombs of Mang's wife, sons, father, and ancestors, burned their coffins and the Nine Temples, Bright Hall, and Imperial Academy, and fire lit up the city.", idiomatic: "The troops dug up the tombs of Wang Mang's wife, sons, father, and ancestors, burned their coffins and the Nine Temples, Bright Hall, and Imperial Academy, and fire lit the city." },
  { zh: "九月，戊申朔，兵從宣平城門入。", literal: "In the ninth month, on the new moon of the day wushen, troops entered through Xuanyang Gate.", idiomatic: "In the ninth month, on the new moon of the day wushen, troops entered through Xuanyang Gate." },
  { zh: "張邯逢兵見殺；", literal: "Zhang Han met troops and was killed;", idiomatic: "Zhang Han met troops and was killed;" },
  { zh: "王邑、王林、王巡、帶足惲等分將兵距擊北闕下，會日暮，官府、邸第盡奔亡。", literal: "Wang Yi, Wang Lin, Wang Xun, Dai Zuyun, and others separately led troops to resist and strike below the northern gate-tower; as night fell, government offices and noble mansions all fled and were abandoned.", idiomatic: "Wang Yi, Wang Lin, Wang Xun, Dai Zuyun, and others separately led troops to resist below the northern gate-tower; as night fell, government offices and noble mansions were all abandoned." },
  { zh: "己酉，城中少年朱弟、張魚等恐見鹵掠，趨讙並和，燒作室門，斧敬法闥，呼曰：「反虜王莽，何不出降！", literal: "On the day jiyou the youths of the city Zhu Di, Zhang Yu, and others, fearing they would be plundered, rushed shouting and joined in chorus, burned the workroom gates, axed the law offices' doors, and cried: \"The rebel Wang Mang—why do you not come out and surrender!", idiomatic: "On the day jiyou the youths Zhu Di, Zhang Yu, and others of the city, fearing plunder, rushed shouting in unison, burned the workroom gates, axed the law offices' doors, and cried: \"Rebel Wang Mang—why do you not surrender!" },
  { zh: "」火及掖庭、承明，黃皇室主所居。", literal: "\" Fire reached the Rear Palace and Chenming, where the Yellow Imperial Lady dwelt.", idiomatic: "\" Fire reached the Rear Palace and Chenming, where the Yellow Imperial Lady dwelt." },
  { zh: "黃皇室主曰：「何面目以見漢家！", literal: "The Yellow Imperial Lady said: \"With what face can I meet the house of Han!", idiomatic: "The Yellow Imperial Lady said: \"With what face can I meet the house of Han!" },
  { zh: "」自投火中而死。", literal: "\" She threw herself into the fire and died.", idiomatic: "\" She threw herself into the fire and died." },
  { zh: "莽避火宣室前殿，火輒隨之。", literal: "Mang avoided the fire in the front hall of the Xuan Chamber; the fire always followed him.", idiomatic: "Wang Mang fled the fire to the front hall of the Xuan Chamber, but the fire always followed him." },
  { zh: "莽紺袀服，持虞帝匕首，天文郎按式於前，莽旋席隨斗柄而坐，曰：「天生德於予，漢兵其如予何！", literal: "Mang wore dark crimson ceremonial dress, held the Shun Emperor's dagger, the astronomical officer held the armillary before him; Mang turned his mat following the Dipper's handle and sat, saying: \"Heaven gave virtue to me—what can Han troops do to me!", idiomatic: "Wang Mang wore dark crimson ceremonial dress, held the Shun Emperor's dagger, the astronomical officer held the armillary before him; Mang turned his mat following the Dipper's handle and sat, saying: \"Heaven gave virtue to me—what can Han troops do to me!" },
  { zh: "」庚戌，旦明，群臣扶掖莽自前殿之漸台，欲阻池水，公卿從官尚千餘人隨之。", literal: "\" On the day gengxu, at dawn, the ministers supported Mang from the front hall to the tiered terrace, intending to block the pool water; upper dukes and attending officials, more than a thousand, followed.", idiomatic: "\" On the day gengxu, at dawn, the ministers supported Wang Mang from the front hall to the tiered terrace by the pool; more than a thousand upper dukes and attendants followed." },
  { zh: "王邑晝夜戰，罷極，士死傷略盡；", literal: "Wang Yi fought day and night, utterly exhausted, soldiers dead and wounded nearly all gone;", idiomatic: "Wang Yi fought day and night until utterly exhausted and his soldiers were nearly all dead or wounded;" },
  { zh: "馳入宮，間關至漸台，見其子侍中睦解衣冠欲逃，邑叱之，令還，父子共守莽。", literal: "he galloped into the palace, threading danger to the tiered terrace, saw his son Attendant-in-Ordinary Mu removing cap and robes intending to flee; Yi shouted at him and ordered him back—the father and son together guarded Mang.", idiomatic: "he galloped into the palace, threading danger to the tiered terrace, saw his son Attendant-in-Ordinary Mu removing his cap and robes to flee; Yi shouted him back, and father and son together guarded Wang Mang." },
  { zh: "軍人入殿中，聞莽在漸台，眾共圍之數百重。", literal: "Soldiers entered the hall; hearing Mang was on the tiered terrace, the multitude together surrounded it in hundreds of rings.", idiomatic: "Soldiers entered the hall; hearing Wang Mang was on the tiered terrace, the multitude surrounded it in hundreds of rings." },
  { zh: "台上猶與相射，矢盡，短兵接。", literal: "On the terrace they still shot at one another; when arrows were spent they closed with short weapons.", idiomatic: "On the terrace they still shot at one another; when arrows were spent they closed with short weapons." },
  { zh: "王邑父子、帶++足惲、王巡戰死，莽入室。", literal: "Wang Yi father and son, Dai++ Zuyun, and Wang Xun died in battle; Mang entered the inner room.", idiomatic: "Wang Yi and his son, Dai Zuyun, and Wang Xun died in battle; Wang Mang entered the inner room." },
  { zh: "下餔時，眾兵上台，苗訢、唐尊、王盛等皆死。", literal: "At the hour of the lower meal the multitude of troops mounted the terrace; Miao Xin, Tang Zun, Wang Sheng, and others all died.", idiomatic: "At the hour of the lower meal the troops mounted the terrace; Miao Xin, Tang Zun, Wang Sheng, and others all died." },
  { zh: "商人杜吳殺莽，校尉東海公賓就斬莽首；", literal: "The merchant Du Wu killed Mang; Colonel Marquis of Donghai Gong Bin Jiu cut off Mang's head;", idiomatic: "The merchant Du Wu killed Wang Mang; Colonel Marquis of Donghai Gong Bin Jiu cut off his head;" },
  { zh: "軍人分莽身，節解臠分，爭相殺者數十人。", literal: "soldiers divided Mang's body, severed joints and sliced flesh and divided it, and several tens killed one another contending.", idiomatic: "soldiers divided his body, severed the joints and sliced the flesh, and several tens killed one another in the scramble." },
  { zh: "公賓就持莽首詣王憲。", literal: "Gong Bin Jiu took Mang's head and went to Wang Xian.", idiomatic: "Gong Bin Jiu took Wang Mang's head to Wang Xian." },
  { zh: "憲自稱漢大將軍，城中兵數十萬皆屬焉。", literal: "Xian styled himself Han great general; the city's troops, several hundred thousand, all submitted to him.", idiomatic: "Xian styled himself Han great general, and the city's several hundred thousand troops all submitted to him." },
  { zh: "捨東宮，妻莽後宮，乘其車服。", literal: "He occupied the Eastern Palace, took Mang's harem wives, and rode his chariots and robes.", idiomatic: "He occupied the Eastern Palace, took Wang Mang's consorts, and used his chariots and robes." },
  { zh: "癸丑，李松、鄧曄入長安，將軍趙萌、申屠建亦至。", literal: "On the day guichou Li Song and Deng Ye entered Chang'an; Generals Zhao Meng and Shentu Jian also arrived.", idiomatic: "On the day guichou Li Song and Deng Ye entered Chang'an; Generals Zhao Meng and Shentu Jian also arrived." },
  { zh: "以王憲得璽綬不上，多挾宮女，建天子鼓旗，收斬之。", literal: "Because Wang Xian had obtained the seal-cord and not presented it, kept many palace women, and raised the Son of Heaven's drums and banners, they seized and executed him.", idiomatic: "Because Wang Xian had obtained the imperial seal and not presented it, kept many palace women, and raised the Son of Heaven's drums and banners, they seized and executed him." },
  { zh: "傳莽首詣宛，縣於市。", literal: "Mang's head was sent to Wan and hung in the market.", idiomatic: "Wang Mang's head was sent to Wan and hung in the market." },
  { zh: "百姓共提擊之，或切食其舌。", literal: "The common people together struck and beat it; some cut off and ate his tongue.", idiomatic: "The people together struck and beat it; some cut off and ate his tongue." },
  { zh: "班固贊曰：王莽始起外戚，折節力行以要名譽，及居位輔政，勤勞國家，直道而行，豈所謂「色取仁而行違」者邪！", literal: "Ban Gu's praise says: Wang Mang at first rose from the maternal kin, bent his will and practiced conduct to win reputation; when he held office and assisted government he toiled for the state and walked the straight path—was he not what is called \"taking benevolence in appearance yet acting contrary\"!", idiomatic: "Ban Gu's praise says: Wang Mang at first rose from the maternal kin, bent his will and practiced conduct to win reputation; when he held office and assisted government he toiled for the state and walked the straight path—was he not what is called \"appearing benevolent yet acting contrary\"!" },
  { zh: "莽既不仁而有佞邪之材，又乘四父歷世之權，遭漢中微，國統三絕，而太后壽考，為之宗主，故得肆其奸慝以成篡盜之禍。", literal: "Mang was unbenevolent yet had sycophantic and perverse talent; he also rode the power of four fathers through successive reigns, encountered Han's mid-decline and the succession thrice cut off, while the empress dowager lived long as his clan lord—therefore he could unleash his treachery and wickedness to complete the calamity of usurpation and theft.", idiomatic: "Wang Mang was unbenevolent yet possessed sycophantic and perverse talent; he also rode the power of four Wang fathers through successive reigns, encountered Han's mid-decline with the succession thrice cut off, while the empress dowager lived long as his patron—therefore he could unleash his treachery to complete the calamity of usurpation." },
  { zh: "推是言之，亦天時，非人力之致矣！", literal: "Pushing this to speak of it, it was also Heaven's season—not something human effort could bring about!", idiomatic: "Pushed to its conclusion, it was also Heaven's season—not something human effort alone could bring about!" },
  { zh: "及其竊位南面，顛覆之勢險於桀、紂，而莽晏然自以黃、虞復出也，乃始恣睢，奮其威詐，毒流諸夏，亂延蠻貉，猶未足逞其欲焉。", literal: "When he stole the throne and faced south, the peril of overthrow was more dangerous than Jie and Zhou—yet Mang was placid and took himself to be the Yellow Emperor and Shun reborn; only then did he begin to run riot, exert his might and fraud, poison flowing through all Xia, disorder extending to barbarians and Mo—still not enough to satisfy his desires.", idiomatic: "When he stole the throne and faced south, the peril of overthrow exceeded Jie and Zhou—yet Wang Mang calmly took himself to be the Yellow Emperor and Shun reborn; only then did he run riot, exert his might and fraud, send poison through all Xia and disorder to the barbarians—still not enough to satisfy his desires." },
  { zh: "是以四海之內，囂然喪其樂生之心，中外憤怨，遠近俱發，城池不守，支體分裂，遂令天下城邑為虛，害遍生民，自書傳所載亂臣賊子，考其禍敗，未有如莽之甚者也！", literal: "Therefore within the four seas people clamorously lost their hearts' joy in life; within and without were anger and resentment, far and near all rose up, cities and walls could not be held, limbs were split apart—thereby making the realm's cities and towns empty, harm spreading over the living people; from what books and traditions record of rebellious ministers and traitorous sons, examining their disasters and defeats, none has been like Mang's extremity!", idiomatic: "Therefore within the four seas people clamorously lost their joy in life; anger and resentment rose within and without, far and near all rebelled, cities could not be held, the realm split apart—until the empire's towns stood empty and harm spread over the living; among rebellious ministers and traitorous sons recorded in books and traditions, none suffered defeat like Wang Mang's!" },
  { zh: "昔秦燔《詩》、《書》以立私議，莽誦《六藝》以文奸言，同歸殊塗，俱用滅亡。", literal: "Formerly Qin burned the Odes and Documents to establish private opinion; Mang recited the Six Arts to ornament treacherous words—same end by different paths, both used and perished.", idiomatic: "Formerly Qin burned the Odes and Documents to establish private opinion; Wang Mang recited the Six Arts to ornament treacherous words—same end by different paths, both led to ruin." },
  { zh: "皆聖王之驅除云爾。", literal: "All were what the sage kings drove out and removed.", idiomatic: "All were what the sage kings drove out and removed." },
  { zh: "定國上公王匡拔洛陽，生縛莽太師王匡、哀章，皆斬之。", literal: "Stabilize-the-Realm Upper Duke Wang Kuang took Luoyang, bound alive Mang's Grand Preceptor Wang Kuang and Ai Zhang, and both were beheaded.", idiomatic: "Stabilize-the-Realm Upper Duke Wang Kuang took Luoyang, bound alive Wang Mang's Grand Preceptor Wang Kuang and Ai Zhang, and beheaded them both." },
  { zh: "冬，十月，奮威大將軍劉信擊殺劉望於汝南，並誅嚴尤、陳茂，郡縣皆降。", literal: "In winter, the tenth month, Manifest Might Grand General Liu Xin killed Liu Wang at Runan and also executed Yan You and Chen Mao; commanderies and counties all surrendered.", idiomatic: "In winter, the tenth month, Manifest Might Grand General Liu Xin killed Liu Wang at Runan and also executed Yan You and Chen Mao; commanderies and counties all surrendered." },
  { zh: "更始將都洛陽，以劉秀行司隸校尉，使前整修宮府。", literal: "The Gengshi Emperor was about to make Luoyang his capital and appointed Liu Xiu Acting Director of the Retainers, sending him ahead to repair the palace offices.", idiomatic: "The Gengshi Emperor was about to make Luoyang his capital and appointed Liu Xiu Acting Director of the Retainers, sending him ahead to repair the palace offices." },
  { zh: "秀乃致僚屬，作文移，從事司察，一如舊章。", literal: "Xiu then summoned his staff, issued written orders, and had his attendants investigate and inspect according to the old regulations.", idiomatic: "Xiu then summoned his staff, issued written orders, and had his attendants investigate and inspect according to the old regulations." },
  { zh: "時三輔吏士東迎更始，見諸將過，皆冠幘而服婦人衣，莫不笑之。", literal: "At the time the officials and gentry of the Three Metropolises were coming east to welcome the Gengshi Emperor; when they saw the various generals pass by, all wore caps with towels and women's clothing, and none failed to laugh.", idiomatic: "At the time the officials and gentry of the Three Metropolises were coming east to welcome the Gengshi Emperor; when they saw the various generals pass by, all wore caps with towels and women's clothing, and none failed to laugh." },
  { zh: "及見司隸僚屬，皆歡喜不自勝，老吏或垂涕曰：「不圖今日復見漢官威儀！", literal: "When they saw the Director of the Retainers' staff, they were all so overjoyed they could not contain themselves; some old officials even wept and said: \"I never thought I would live to see again the majesty of Han officials!", idiomatic: "When they saw the Director of the Retainers' staff, they were all so overjoyed they could not contain themselves; some old officials even wept and said, \"I never thought I would live to see again the majesty of Han officials!\"" },
  { zh: "」由是識者皆屬心焉。", literal: "\" From this those with insight all pledged their hearts to him.", idiomatic: "\" From this those with insight all pledged their hearts to him." },
  { zh: "更始北都洛陽，分遣使者徇郡國，曰：「先降者復爵位！", literal: "The Gengshi Emperor moved the capital north to Luoyang and sent envoys separately through commanderies and states, saying: \"Those who surrender first will have their ranks and titles restored!", idiomatic: "The Gengshi Emperor moved the capital north to Luoyang and sent envoys separately through commanderies and states, saying, \"Those who surrender first will have their ranks and titles restored!\"" },
  { zh: "」使者至上谷，上谷太守扶風耿況迎，上印綬；", literal: "\" When the envoy reached Shanggu, Shanggu Administrator Geng Kuang of Fufeng welcomed him and handed over his seal and cord;", idiomatic: "\" When the envoy reached Shanggu, Shanggu Administrator Geng Kuang of Fufeng welcomed him and handed over his seal and cord;" },
  { zh: "使者納之，一宿，無還意。", literal: "the envoy accepted them and after one night showed no intention of returning them.", idiomatic: "the envoy accepted them and after one night showed no intention of returning them." },
  { zh: "功曹寇恂勒兵入見使者，請之，使者不與，曰：「天王使者，功曹欲脅之邪！", literal: "Staff Officer Kou Xun led troops in to see the envoy and requested them back; the envoy would not give them, saying: \"Imperial envoy of the Heavenly King—does the staff officer wish to coerce him?!", idiomatic: "Staff Officer Kou Xun led troops in to see the envoy and requested them back; the envoy would not give them, saying, \"Imperial envoy of the Heavenly King—does the staff officer wish to coerce him?!\"" },
  { zh: "」恂曰：「非敢脅使君，竊傷計之不詳也。", literal: "\" Xun said: \"I dare not coerce Your Grace; I merely grieve that the plan is ill-considered.", idiomatic: "\" Xun said, \"I dare not coerce Your Grace; I merely grieve that the plan is ill-considered.\"" },
  { zh: "今天下初定，使君建節銜命，郡國莫不延頸傾耳。", literal: "Now the realm is newly settled, and Your Grace bears the imperial staff and mandate; every commandery and state stretches its neck and inclines its ear.", idiomatic: "Now the realm is newly settled, and Your Grace bears the imperial staff and mandate; every commandery and state stretches its neck and inclines its ear." },
  { zh: "今始至上谷而先墮大信，將復何以號令他郡乎！", literal: "Now at the very first arrival at Shanggu you first destroy this great trust—how thereafter will you command the other commanderies?!", idiomatic: "Now at the very first arrival at Shanggu you first destroy this great trust—how thereafter will you command the other commanderies?!\"" },
  { zh: "」使者不應。", literal: "\" The envoy did not answer.", idiomatic: "\" The envoy did not answer." },
  { zh: "恂叱左右以使者命召況；", literal: "Xun shouted to those at his side to summon Kuang by the envoy's authority;", idiomatic: "Xun shouted to those at his side to summon Kuang by the envoy's authority;" },
  { zh: "況至，恂進取印綬帶況。", literal: "when Kuang arrived, Xun advanced and took back the seal and cord to fasten on Kuang.", idiomatic: "when Kuang arrived, Xun advanced and took back the seal and cord to fasten on Kuang." },
  { zh: "使者不得已，乃承製詔之，況受而歸。", literal: "The envoy had no choice and thereupon issued an imperial edict confirming him; Kuang received it and returned.", idiomatic: "The envoy had no choice and thereupon issued an imperial edict confirming him; Kuang received it and returned." },
  { zh: "宛人彭寵、吳漢亡命在漁陽，鄉人韓鴻為更始使，徇北州，承製拜寵偏將軍，行漁陽太守事，以漢為安樂令。", literal: "Peng Chong of Wan and Wu Han, outlaws at Yuyang—a fellow townsman Han Hong served as Gengshi envoy touring the northern provinces, and by imperial order enfeoffed Chong as Acting General and Acting Administrator of Yuyang, and Han as Administrator of Anle.", idiomatic: "Peng Chong of Wan and Wu Han, outlaws at Yuyang—a fellow townsman Han Hong served as Gengshi envoy touring the northern provinces, and by imperial order enfeoffed Chong as Acting General and Acting Administrator of Yuyang, and Han as Administrator of Anle." },
  { zh: "更始遣使降赤眉。", literal: "The Gengshi Emperor sent envoys to accept the surrender of the Chimei.", idiomatic: "The Gengshi Emperor sent envoys to accept the surrender of the Chimei." },
  { zh: "樊崇等聞漢室復興，即留其兵，將渠帥二十餘人隨使者至洛陽，更始皆封為列侯。", literal: "Fan Chong and others, hearing the Han house was restored, at once left their troops; more than twenty chieftains and commanders followed the envoy to Luoyang, and the Gengshi Emperor all enfeoffed them as ranked marquises.", idiomatic: "Fan Chong and others, hearing the Han house was restored, at once left their troops; more than twenty chieftains and commanders followed the envoy to Luoyang, and the Gengshi Emperor all enfeoffed them as ranked marquises." },
  { zh: "崇等既未有國邑，而留眾稍有離叛者，乃覆亡歸其營。", literal: "Chong and the others had as yet no fiefs, and of those left behind some gradually rebelled; they then fled and returned to their camps.", idiomatic: "Chong and the others had as yet no fiefs, and of those left behind some gradually rebelled; they then fled and returned to their camps." },
  { zh: "王莽廬江連率穎川李憲據郡自守，稱淮南王。", literal: "Li Xian of Yingchuan, the former Lian commandant of Wang Mang's Lujiang, held the commandery and defended himself, styling himself King of Huainan.", idiomatic: "Li Xian of Yingchuan, the former Lian commandant of Wang Mang's Lujiang, held the commandery and defended himself, styling himself King of Huainan." },
  { zh: "故梁王立之子永詣洛陽；", literal: "Liu Yong, son of the former King of Liang Li, went to Luoyang;", idiomatic: "Liu Yong, son of the former King of Liang Li, went to Luoyang;" },
  { zh: "更始封為梁王，都睢陽。", literal: "the Gengshi Emperor enfeoffed him as King of Liang with his capital at Suiyang.", idiomatic: "the Gengshi Emperor enfeoffed him as King of Liang with his capital at Suiyang." },
  { zh: "更始欲令親近大將徇河北，大司徒賜言：「諸家子獨有文叔可用。", literal: "The Gengshi Emperor wished to send a close relative or great general to tour Hebei; Grand Minister Liu Ci said: \"Among all the clan sons only Wen Shu is usable.", idiomatic: "The Gengshi Emperor wished to send a close relative or great general to tour Hebei; Grand Minister Liu Ci said, \"Among all the clan sons only Wen Shu is usable.\"" },
  { zh: "」朱鮪等以為不可，更始狐疑，賜深勸之。", literal: "\" Zhu Wei and others thought it could not be done; the Gengshi Emperor wavered, and Ci urged him strongly.", idiomatic: "\" Zhu Wei and others thought it could not be done; the Gengshi Emperor wavered, and Ci urged him strongly." },
  { zh: "更始乃以劉秀行大司馬事，持節北渡河，鎮慰州郡。", literal: "The Gengshi Emperor thereupon appointed Liu Xiu Acting Grand Marshal, bearing the staff to cross the Yellow River north and pacify and comfort the provinces and commanderies.", idiomatic: "The Gengshi Emperor thereupon appointed Liu Xiu Acting Grand Marshal, bearing the staff to cross the Yellow River north and pacify and comfort the provinces and commanderies." },
  { zh: "以大司徒賜為丞相，令先入關修宗廟、宮室。", literal: "Grand Minister Liu Ci was made Chancellor and ordered to enter the passes first to repair the ancestral temples and palaces.", idiomatic: "Grand Minister Liu Ci was made Chancellor and ordered to enter the passes first to repair the ancestral temples and palaces." },
  { zh: "大司馬秀至河北，所過郡縣，考察官吏，黜陟能否，平遣囚徒，除王莽苛政，復漢官名。", literal: "Acting Grand Marshal Xiu reached Hebei; in every commandery and county he passed he examined officials, promoted and demoted according to ability, fairly released prisoners, abolished Wang Mang's harsh policies, and restored Han official titles.", idiomatic: "Acting Grand Marshal Xiu reached Hebei; in every commandery and county he passed he examined officials, promoted and demoted according to ability, fairly released prisoners, abolished Wang Mang's harsh policies, and restored Han official titles." },
  { zh: "吏民喜悅，爭持牛酒迎勞，秀皆不受。", literal: "Officials and commoners rejoiced and vied to present oxen and wine to welcome and honor him; Xiu declined all.", idiomatic: "Officials and commoners rejoiced and vied to present oxen and wine to welcome and honor him; Xiu declined all." },
  { zh: "南陽鄧禹杖策追秀，及於鄴。", literal: "Deng Yu of Nanyang, staff in hand, pursued Xiu and caught him at Ye.", idiomatic: "Deng Yu of Nanyang, staff in hand, pursued Xiu and caught him at Ye." },
  { zh: "秀曰：「我得專封拜，生遠來，寧欲仕乎？", literal: "Xiu said: \"I now have sole authority to enfeoff and appoint—having come from afar, do you wish an office?", idiomatic: "Xiu said, \"I now have sole authority to enfeoff and appoint—you have come from afar; do you wish an office?\"" },
  { zh: "」禹曰：「不願也。", literal: "\" Yu said: \"I do not.", idiomatic: "\" Yu said, \"I do not.\"" },
  { zh: "」秀曰：「即如是，何欲為？", literal: "\" Xiu said: \"If so, what do you wish?", idiomatic: "\" Xiu said, \"If so, what do you wish?\"" },
  { zh: "」禹曰：「但願明公威德加於四海，禹得效其尺寸，垂功名於竹帛耳！", literal: "\" Yu said: \"I only wish that Your Grace's prestige and virtue extend to the four seas, and that I may render my small measure and leave my fame on bamboo and silk!\"", idiomatic: "\" Yu said, \"I only wish that Your Grace's prestige and virtue extend to the four seas, and that I may render my small measure and leave my fame on bamboo and silk!\"" },
  { zh: "」秀笑，因留宿間語。", literal: "\" Xiu laughed and thereupon kept him overnight for private talk.", idiomatic: "\" Xiu laughed and thereupon kept him overnight for private talk." },
  { zh: "禹進說曰：「今山東未安，赤眉、青犢之屬動以萬數。", literal: "Yu advanced his counsel, saying: \"Now Shandong is not yet settled; the Chimei, Green Calves, and their kind move in tens of thousands.", idiomatic: "Yu advanced his counsel, saying, \"Now Shandong is not yet settled; the Chimei, Green Calves, and their kind move in tens of thousands." },
  { zh: "更始既是常才而不自聽斷，諸將皆庸人屈起，志在財幣，爭用威力。", literal: "The Gengshi Emperor is by capacity ordinary and does not decide for himself; the generals are all mediocrity risen by chance, their aim wealth, contending in the use of force.", idiomatic: "The Gengshi Emperor is by capacity ordinary and does not decide for himself; the generals are all mediocrity risen by chance, their aim wealth, contending in the use of force." },
  { zh: "朝夕自快而已，非有忠良明智、深慮遠圖，欲尊主安民者也。", literal: "They seek daily self-pleasure alone—none are loyal and good, wise and intelligent, with deep thought and far vision, wishing to honor the ruler and settle the people.", idiomatic: "They seek daily self-pleasure alone—none are loyal and good, wise and intelligent, with deep thought and far vision, wishing to honor the ruler and settle the people." },
  { zh: "歷觀往古聖人之興，二科而已，天時與人事也。", literal: "Surveying past ages, the rise of sage rulers has only two categories: heavenly timing and human affairs.", idiomatic: "Surveying past ages, the rise of sage rulers has only two categories: heavenly timing and human affairs." },
  { zh: "今以天時觀之，更始既立而災變方興；", literal: "Viewed by heavenly timing, the Gengshi Emperor has just been enthroned while omens and disasters are rising;", idiomatic: "Viewed by heavenly timing, the Gengshi Emperor has just been enthroned while omens and disasters are rising;" },
  { zh: "以人事觀之，帝王大業非凡夫所任，分崩離析，形勢可見。", literal: "viewed by human affairs, the great enterprise of emperors and kings is not what ordinary men can bear—fragmentation and division, the trend already visible.", idiomatic: "viewed by human affairs, the great enterprise of emperors and kings is not what ordinary men can bear—fragmentation and division, the trend already visible." },
  { zh: "明公雖建籓輔之功，猶恐無所成立也。", literal: "Your Grace, though you have built the merit of supporting the fief, still fears having nothing established.", idiomatic: "Your Grace, though you have built the merit of supporting the fief, still fears having nothing established." },
  { zh: "況明公素有盛德大功，為天下所向服，軍政齊肅，賞罰明信。", literal: "Moreover Your Grace has always had great virtue and great achievement, winning the submission of all under Heaven; military and civil affairs are uniformly disciplined, rewards and punishments clear and believed.", idiomatic: "Moreover Your Grace has always had great virtue and great achievement, winning the submission of all under Heaven; military and civil affairs are uniformly disciplined, rewards and punishments clear and believed." },
  { zh: "為今之計，莫如延攬英雄，務悅民心，立高祖之業，救萬民之命。", literal: "For the present plan, nothing surpasses gathering heroes and striving to please the people's hearts, founding Gaozu's enterprise, and saving the lives of the myriad people.", idiomatic: "For the present plan, nothing surpasses gathering heroes and striving to please the people's hearts, founding Gaozu's enterprise, and saving the lives of the myriad people." },
  { zh: "以公而慮，天下不足定也。", literal: "Considering it with Your Grace's qualities, settling the realm is not difficult.", idiomatic: "Considering it with Your Grace's qualities, settling the realm is not difficult." },
  { zh: "」秀大悅，因令禹常宿止於中，與定計議。", literal: "\" Xiu was greatly pleased and thereupon had Yu regularly lodge within his quarters and settle plans with him.", idiomatic: "\" Xiu was greatly pleased and thereupon had Yu regularly lodge within his quarters and settle plans with him." },
  { zh: "每任使諸將，多訪於禹，皆當其才。", literal: "Whenever he assigned generals, he mostly consulted Yu; all matched their talents.", idiomatic: "Whenever he assigned generals, he mostly consulted Yu; all matched their talents." },
  { zh: "秀自兄縯之死，每獨居輒不御酒肉，枕席有涕泣處，主簿馮異獨叩頭寬譬，秀止之曰：「卿勿妄言！", literal: "Since his elder brother Yan's death, whenever Xiu was alone he would not use wine or meat; on pillow and mat were traces of weeping; Chief Clerk Feng Yi alone kowtowed to comfort and explain, and Xiu stopped him, saying: \"Do not speak rashly!", idiomatic: "Since his elder brother Yan's death, whenever Xiu was alone he would not use wine or meat; on pillow and mat were traces of weeping; Chief Clerk Feng Yi alone kowtowed to comfort and explain, and Xiu stopped him, saying, \"Do not speak rashly!\"" },
  { zh: "」異因進說曰：「更始政亂，百姓無所依戴。", literal: "\" Yi thereupon advanced his counsel, saying: \"The Gengshi Emperor's government is chaotic; the people have nothing to rely on.", idiomatic: "\" Yi thereupon advanced his counsel, saying, \"The Gengshi Emperor's government is chaotic; the people have nothing to rely on.\"" },
  { zh: "夫人久飢渴，易為充飽。", literal: "A man long hungry and thirsty is easily satisfied with a full meal.", idiomatic: "A man long hungry and thirsty is easily satisfied with a full meal." },
  { zh: "今公專命方面，宜分遣官屬徇行郡縣，宣佈惠澤。", literal: "Now Your Grace holds sole authority in the region; you should send out your officers to tour commanderies and counties and proclaim benevolent favor.", idiomatic: "Now Your Grace holds sole authority in the region; you should send out your officers to tour commanderies and counties and proclaim benevolent favor." },
  { zh: "」秀納之。", literal: "\" Xiu accepted this.", idiomatic: "\" Xiu accepted this." },
  { zh: "騎都尉宋子耿純謁秀於邯鄲，退，見官屬將兵法度不與它將同，遂自結納。", literal: "Colonel of the Cavalry Song Chun of Zi and Geng Chun called on Xiu at Handan; on leaving he saw that military law and regulations among his officers differed from other generals', and thereupon attached himself.", idiomatic: "Colonel of the Cavalry Song Chun of Zi and Geng Chun called on Xiu at Handan; on leaving he saw that military law and regulations among his officers differed from other generals', and thereupon attached himself." },
  { zh: "故趙繆王子林說秀決列人河水以灌赤眉，秀不從；", literal: "Liu Lin, son of the former Prince of Zhao Musu, urged Xiu to breach the dams of the Li River to flood the Chimei; Xiu did not follow;", idiomatic: "Liu Lin, son of the former Prince of Zhao Musu, urged Xiu to breach the dams of the Li River to flood the Chimei; Xiu did not follow;" },
  { zh: "去之真定。", literal: "he left for Zhending.", idiomatic: "he left for Zhending." },
  { zh: "林素任俠於趙、魏間。", literal: "Lin had always been a knight-errant between Zhao and Wei.", idiomatic: "Lin had always been a knight-errant between Zhao and Wei." },
  { zh: "王莽時，長安中有自稱成帝子子輿者，莽殺之。", literal: "In Wang Mang's time, in Chang'an someone styled himself Emperor Cheng's son Ziyu; Mang killed him.", idiomatic: "In Wang Mang's time, in Chang'an someone styled himself Emperor Cheng's son Ziyu; Wang Mang killed him." },
  { zh: "邯鄲卜者王郎緣是詐稱真子輿，云「母故成帝謳者，嘗見黃氣從上下，遂任身；", literal: "The diviner Wang Lang of Handan seized on this and falsely claimed to be the true Ziyu, saying: \"My mother was formerly Emperor Cheng's songstress; she once saw yellow qi descend from above, and she thereupon conceived;", idiomatic: "The diviner Wang Lang of Handan seized on this and falsely claimed to be the true Ziyu, saying, \"My mother was formerly Emperor Cheng's songstress; she once saw yellow qi descend from above, and she thereupon conceived;\"" },
  { zh: "趙後欲害之，偽易它人子，以故得全。", literal: "the Queen of Zhao wished to harm him, and by pretense exchanged another man's child, and so he was preserved whole.", idiomatic: "the Queen of Zhao wished to harm him, and by pretense exchanged another man's child, and so he was preserved whole.\"" },
  { zh: "」林等信之，與趙國大豪李育、張參等謀共立郎。", literal: "\" Lin and others believed him; with the great clansmen of Zhao Li Yu and Zhang Can they plotted jointly to establish Lang.", idiomatic: "\" Lin and others believed him; with the great clansmen of Zhao Li Yu and Zhang Can they plotted jointly to establish Lang." },
  { zh: "會民間傳赤眉將渡河，林等因此宣言「赤眉當立劉子輿」，以觀眾心，百姓多信之。", literal: "When it was rumored among the people that the Chimei would cross the river, Lin and others used this to proclaim \"the Chimei will establish Liu Ziyu,\" to test popular sentiment; the common people mostly believed it.", idiomatic: "When it was rumored among the people that the Chimei would cross the river, Lin and others used this to proclaim \"the Chimei will establish Liu Ziyu,\" to test popular sentiment; the common people mostly believed it." },
  { zh: "十二月，林等率車騎數百晨入邯鄲城，止於王宮，立郎為天子；", literal: "In the twelfth month, Lin and others led several hundred chariots and horsemen at dawn into Handan city, stopping at the royal palace, and established Lang as Son of Heaven;", idiomatic: "In the twelfth month, Lin and others led several hundred chariots and horsemen at dawn into Handan city, stopping at the royal palace, and established Lang as Son of Heaven;" },
  { zh: "分遣將帥徇下幽、冀，移檄州郡，趙國以北、遼東以西皆望風響應。", literal: "they sent generals separately to subdue You and Ji, issued proclamations to provinces and commanderies, and from north of Zhao to west of Liaodong all responded at the mere report of wind.", idiomatic: "they sent generals separately to subdue You and Ji, issued proclamations to provinces and commanderies, and from north of Zhao to west of Liaodong all responded at the mere report of wind." },
  { zh: "春，正月，大司馬秀以王郎新盛，乃北徇薊。", literal: "In spring, the first month, Acting Grand Marshal Xiu, because Wang Lang was newly strong, turned north to campaign in Ji.", idiomatic: "In spring, the first month, Acting Grand Marshal Xiu, because Wang Lang was newly strong, turned north to campaign in Ji." },
  { zh: "申屠建、李松自長安迎更始遷都。", literal: "Shentu Jian and Li Song from Chang'an welcomed the Gengshi Emperor to move the capital.", idiomatic: "Shentu Jian and Li Song from Chang'an welcomed the Gengshi Emperor to move the capital." },
  { zh: "二月，更始發洛陽。", literal: "In the second month, the Gengshi Emperor set out from Luoyang.", idiomatic: "In the second month, the Gengshi Emperor set out from Luoyang." },
  { zh: "初，三輔豪桀假號誅莽者，人人皆望封侯。", literal: "Initially the powerful men of the Three Metropolises who raised banners to execute Wang Mang each hoped for enfeoffment as marquis.", idiomatic: "Initially the powerful men of the Three Metropolises who raised banners to execute Wang Mang each hoped for enfeoffment as marquis." },
  { zh: "申屠建既斬王憲，又揚言「三輔兒大黠，共殺其主。", literal: "Shentu Jian, having already beheaded Wang Xian, also proclaimed loudly: \"The children of the Three Metropolises are too cunning—they jointly killed their master.", idiomatic: "Shentu Jian, having already beheaded Wang Xian, also proclaimed loudly, \"The children of the Three Metropolises are too cunning—they jointly killed their master.\"" },
  { zh: "」吏民惶恐，屬縣屯聚；", literal: "\" Officials and commoners were terrified; dependent counties gathered in armed camps;", idiomatic: "\" Officials and commoners were terrified; dependent counties gathered in armed camps;" },
  { zh: "建等不能下。", literal: "Jian and his party could not subdue them.", idiomatic: "Jian and his party could not subdue them." },
  { zh: "更始至長安，乃下詔大赦，非王莽子，他皆除其罪，於是三輔悉平。", literal: "When the Gengshi Emperor reached Chang'an, he then issued an edict of great amnesty: except for Wang Mang's sons, all others were cleared of guilt, and the Three Metropolises were entirely pacified.", idiomatic: "When the Gengshi Emperor reached Chang'an, he then issued an edict of general amnesty: except for Wang Mang's sons, all others were cleared of guilt, and the Three Metropolises were entirely pacified." },
  { zh: "時長安唯未央宮被焚，其餘宮室、供帳、倉庫、官府皆案堵如故，市裡不改於舊。", literal: "At the time in Chang'an only Weiyang Palace had been burned; the rest of the palaces, furnishings, storehouses, and government offices stood intact as before, and the markets and wards were unchanged from old.", idiomatic: "At the time in Chang'an only Weiyang Palace had been burned; the rest of the palaces, furnishings, storehouses, and government offices stood intact as before, and the markets and wards were unchanged from old." },
  { zh: "更始居長樂宮，升前殿，郎吏以次列庭中。", literal: "The Gengshi Emperor dwelt in Changle Palace and ascended the front hall; gentleman officials lined the court in order.", idiomatic: "The Gengshi Emperor dwelt in Changle Palace and ascended the front hall; gentleman officials lined the court in order." },
  { zh: "更始羞怍，俯首刮席，不敢視。", literal: "The Gengshi Emperor was ashamed and abashed, bowed his head and scraped the mat, and dared not look up.", idiomatic: "The Gengshi Emperor was ashamed and abashed, bowed his head and scraped the mat, and dared not look up." },
  { zh: "諸將後至者，更始問：「虜掠得幾何？", literal: "When the generals who arrived later came, the Gengshi Emperor asked: \"How much did you plunder?", idiomatic: "When the generals who arrived later came, the Gengshi Emperor asked, \"How much did you plunder?\"" },
  { zh: "」左右侍官皆宮省久吏，驚愕相視。", literal: "\" The attendants at his side were all long-serving palace officials; startled, they looked at one another.", idiomatic: "\" The attendants at his side were all long-serving palace officials; startled, they looked at one another." },
  { zh: "李松與棘陽趙萌說更始宜悉王諸功臣；", literal: "Li Song and Zhao Meng of Jiyang urged the Gengshi Emperor that all the meritorious ministers ought to be enfeoffed as kings;", idiomatic: "Li Song and Zhao Meng of Jiyang urged the Gengshi Emperor that all the meritorious ministers ought to be enfeoffed as kings;" },
  { zh: "朱鮪爭之，以為高祖約，非劉氏不王。", literal: "Zhu Wei contested it, saying it was Gaozu's covenant—only those surnamed Liu could be kings.", idiomatic: "Zhu Wei contested it, saying it was Gaozu's covenant—only those surnamed Liu could be kings." },
  { zh: "更始乃先封諸宗室：祉為定陶王，慶為燕王，歙為元氏王，嘉為漢中王，賜為宛王，信為汝陰王，然後立王匡為泚陽王，王鳳為宜城王，朱鮪為膠東王，王常為鄧王，申屠建為平氏王，陳牧為陰平王，衛尉大將軍張卬為淮陽王，執金吾、大將軍廖湛為穰王，尚書胡殷為隨王，柱天大將軍李通為西平王，五威中郎將李軼為舞陰王，水衡大將軍成丹為襄邑王，驃騎大將軍宗佻為穎陰王，尹尊為郾王。", literal: "The Gengshi Emperor thereupon first enfeoffed the clan members: Zhi as King of Dingtao, Qing as King of Yan, Xi as King of Yuanshi, Jia as King of Hanzhong, Ci as King of Wan, Xin as King of Ruynan—then enfeoffed Wang Kuang as King of Ziyang, Wang Feng as King of Yicheng, Zhu Wei as King of Jiaodong, Wang Chang as King of Deng, Shentu Jian as King of Pingshi, Chen Mu as King of Yinping, Guard General Zhang Ang as King of Huaiyang, Commandant of the Capital Li Zhan as King of Rang, Defender of the Palace Hu Yin as King of Sui, Pillar of Heaven General Li Tong as King of Xiping, Wuyi Central Gentleman Li Yi as King of Wuyin, Director of Waters Li Dan as King of Xiangyi, Chief Cavalry General Zong You as King of Yingyin, Yin Zun as King of Yan.", idiomatic: "The Gengshi Emperor thereupon first enfeoffed the clan members: Zhi as King of Dingtao, Qing as King of Yan, Xi as King of Yuanshi, Jia as King of Hanzhong, Ci as King of Wan, Xin as King of Ruynan—then enfeoffed Wang Kuang as King of Ziyang, Wang Feng as King of Yicheng, Zhu Wei as King of Jiaodong, Wang Chang as King of Deng, Shentu Jian as King of Pingshi, Chen Mu as King of Yinping, Guard General Zhang Ang as King of Huaiyang, Commandant of the Capital Li Zhan as King of Rang, Defender of the Palace Hu Yin as King of Sui, Pillar of Heaven General Li Tong as King of Xiping, Wuyi Central Gentleman Li Yi as King of Wuyin, Director of Waters Li Dan as King of Xiangyi, Chief Cavalry General Zong You as King of Yingyin, and Yin Zun as King of Yan." },
  { zh: "唯朱鮪辭不受。", literal: "Only Zhu Wei declined and did not accept.", idiomatic: "Only Zhu Wei declined and did not accept." },
  { zh: "乃以鮪為左大司馬，宛王賜為前大司馬，使與李軼等鎮撫關東。", literal: "He then made Wei Left Grand Marshal, Wan King Ci Front Grand Marshal, and sent them with Li Yi and others to pacify the east of the passes.", idiomatic: "He then made Wei Left Grand Marshal, Wan King Ci Front Grand Marshal, and sent them with Li Yi and others to pacify the east of the passes." },
  { zh: "又使李通鎮荊州，王常行南陽太守事。", literal: "He also sent Li Tong to secure Jingzhou and Wang Chang to act as Administrator of Nanyang.", idiomatic: "He also sent Li Tong to secure Jingzhou and Wang Chang to act as Administrator of Nanyang." },
  { zh: "以李松為丞相，趙萌為右大司馬，共秉內任。", literal: "Li Song was made Chancellor and Zhao Meng Right Grand Marshal, jointly holding inner authority.", idiomatic: "Li Song was made Chancellor and Zhao Meng Right Grand Marshal, jointly holding inner authority." },
  { zh: "更始納趙萌女為夫人，故委政於萌，日夜飲宴後庭。", literal: "The Gengshi Emperor took Zhao Meng's daughter as his lady and therefore entrusted government to Meng, feasting day and night in the rear court.", idiomatic: "The Gengshi Emperor took Zhao Meng's daughter as his lady and therefore entrusted government to Meng, feasting day and night in the rear court." },
  { zh: "群臣欲言事，輒醉不能見，時不得已，乃令侍中坐帷內與語。", literal: "When the ministers wished to speak on affairs, he was always too drunk to receive them; when he had no choice, he had an attendant sit within the curtain to speak with them.", idiomatic: "When the ministers wished to speak on affairs, he was always too drunk to receive them; when he had no choice, he had an attendant sit within the curtain to speak with them." },
  { zh: "韓夫人尤嗜酒，每侍飲，見常侍奏事，輒怒曰：「帝方對我飲，正用此時持事來邪！", literal: "Lady Han loved wine especially; whenever she attended his drinking and saw a regular attendant present a memorial, she would angrily say: \"The Emperor is just drinking with me—why bring affairs at a time like this?!", idiomatic: "Lady Han loved wine especially; whenever she attended his drinking and saw a regular attendant present a memorial, she would angrily say, \"The Emperor is just drinking with me—why bring affairs at a time like this?!\"" },
  { zh: "」起，抵破書案。", literal: "\" She rose and struck and broke the writing desk.", idiomatic: "\" She rose and struck and broke the writing desk." },
  { zh: "趙萌專權，生殺自恣。", literal: "Zhao Meng monopolized power and killed or spared as he pleased.", idiomatic: "Zhao Meng monopolized power and killed or spared as he pleased." },
  { zh: "郎吏有說萌放縱者，更始怒，拔劍斬之，自是無敢復言。", literal: "A gentleman official who said Meng was indulgent—the Gengshi Emperor was angry, drew his sword and beheaded him; from then none dared speak again.", idiomatic: "A gentleman official who said Meng was indulgent—the Gengshi Emperor was angry, drew his sword and beheaded him; from then none dared speak again." },
  { zh: "以至群小、膳夫皆濫授官爵，長安為之語曰：「灶下養，中郎將；", literal: "So that even petty men and cooks were wantonly given offices and ranks; Chang'an made this saying: \"A kitchen hand is made Central Gentleman;", idiomatic: "So that even petty men and cooks were wantonly given offices and ranks; Chang'an made this saying: \"A kitchen hand is made Central Gentleman;\"" },
  { zh: "爛羊胃，騎都尉；", literal: "mutton tripe—a colonel of cavalry;", idiomatic: "mutton tripe—a colonel of cavalry;\"" },
  { zh: "爛羊頭，關內侯。", literal: "mutton head—a marquis within the passes.", idiomatic: "mutton head—a marquis within the passes.\"" },
  { zh: "」軍師將軍李淑上書諫曰：「陛下定業，雖因下江、平林之勢，斯蓋臨時濟用，不可施之既安。", literal: "\" Military Counselor General Li Shu memorialized in remonstrance, saying: \"Your Majesty's settling the enterprise, though it drew on the momentum of Xiajiang and Pinglin, was only for timely need and cannot be applied now that peace is come.", idiomatic: "\" Military Counselor General Li Shu memorialized in remonstrance, saying, \"Your Majesty's settling the enterprise, though it drew on the momentum of Xiajiang and Pinglin, was only for timely need and cannot be applied now that peace is come.\"" },
  { zh: "唯名與器，聖人所重。", literal: "Titles and regalia—sages hold them weighty.", idiomatic: "Titles and regalia—sages hold them weighty." },
  { zh: "今加非其人，望其裨益萬分，猶緣木求魚，升山採珠。", literal: "Now adding them to unfit persons, hoping for the slightest benefit, is like climbing a tree to fish or ascending a mountain for pearls.", idiomatic: "Now adding them to unfit persons, hoping for the slightest benefit, is like climbing a tree to fish or ascending a mountain for pearls." },
  { zh: "海內望此，有以窺度漢祚！", literal: "Within the seas men look on this to gauge the fate of Han!", idiomatic: "Within the seas men look on this to gauge the fate of Han!\"" },
  { zh: "」更始怒，囚之。", literal: "\" The Gengshi Emperor was angry and imprisoned him.", idiomatic: "\" The Gengshi Emperor was angry and imprisoned him." },
  { zh: "諸將在外者皆專行誅賞，各置牧守；", literal: "The generals abroad all exercised executions and rewards on their own authority and each set up governors and prefects;", idiomatic: "The generals abroad all exercised executions and rewards on their own authority and each set up governors and prefects;" },
  { zh: "州郡交錯，不知所從。", literal: "provinces and commanderies overlapped in jurisdiction—none knew whom to follow.", idiomatic: "provinces and commanderies overlapped in jurisdiction—none knew whom to follow." },
  { zh: "由是關中離心，四海怨叛。", literal: "From this Guanzhong lost heart; the four seas resented and rebelled.", idiomatic: "From this Guanzhong lost heart, and the realm resented and rebelled." },
  { zh: "更始征隗囂及其叔父崔、義等，囂將行，方望以為更始成敗未可知，固止之。", literal: "Gengshi campaigned against Wei Xiao and his uncles Cui and Yi and others; as Xiao was about to go, Fang Wang thought Gengshi's success or failure was still unknown and firmly stopped him.", idiomatic: "Gengshi Di campaigned against Wei Xiao and his uncles Cui and Yi; as Xiao was about to depart, Fang Wang thought Gengshi's success was still uncertain and firmly stopped him." },
  { zh: "囂不聽，望以書辭謝而去。", literal: "Xiao would not listen; Wang resigned by letter and left.", idiomatic: "Xiao would not listen; Wang resigned by letter and departed." },
  { zh: "囂等至長安，更始以囂為右將軍，崔、義皆即舊號。", literal: "Xiao and others reached Chang'an; Gengshi made Xiao Right General; Cui and Yi all kept their former titles.", idiomatic: "When Xiao and his party reached Chang'an, Gengshi made Xiao Right General, and Cui and Yi retained their former titles." },
  { zh: "耿況遣其子弇奉奏詣長安，弇時年二十一。", literal: "Geng Kuang sent his son Yan to present a memorial to Chang'an; Yan was then twenty-one.", idiomatic: "Geng Kuang sent his son Yan to present a memorial at Chang'an; Yan was then twenty-one." },
  { zh: "行至宋子，會王郎起，弇從吏孫倉、衛包曰：「劉子輿，成帝正統；", literal: "Reaching Songzi, Wang Lang rose; Yan's attendants Sun Cang and Wei Bao said: \"Liu Ziyu is Emperor Cheng's legitimate line;", idiomatic: "At Songzi, Wang Lang rose; Yan's attendants Sun Cang and Wei Bao said, \"Liu Ziyu is Emperor Cheng's legitimate heir;" },
  { zh: "捨此不歸，遠行安之！", literal: "abandon this and not return—where is safety in going far!", idiomatic: "if you abandon him and do not return, what safety is there in going on?\"" },
  { zh: "」弇按劍曰：「子輿弊賊，卒為降虜耳！", literal: "\" Yan gripped his sword and said: \"Ziyu is a worn-out bandit—he will end a surrendered captive!", idiomatic: "\" Yan gripped his sword and said, \"Ziyu is a spent bandit—he will end a captive in the end!" },
  { zh: "我至長安，與國家陳漁陽、上谷兵馬，歸發突騎，以轔烏合之眾，如摧枯折腐耳。", literal: "When I reach Chang'an I will report to the state the Yuyang and Shanggu troops; returning I will raise sudden cavalry—to crush this mob like snapping dry wood.", idiomatic: "When I reach Chang'an I will report our Yuyang and Shanggu forces to the court; returning I will raise our shock cavalry and crush this mob as one snaps dry wood.\"" },
  { zh: "觀公等不識去就，族滅不久也！", literal: "Seeing you do not know when to stay or go—your clans' extinction is not far!", idiomatic: "Seeing you cannot tell stay from go—your clans' destruction is not far off!\"" },
  { zh: "」倉、包遂亡，降王郎。", literal: "\" Cang and Bao then fled and surrendered to Wang Lang.", idiomatic: "\" Cang and Bao then fled and surrendered to Wang Lang." },
  { zh: "弇聞大司馬秀在盧奴，乃馳北上謁；", literal: "Yan heard Grand Marshal Xiu was at Lunu and galloped north to pay court;", idiomatic: "Yan heard that Grand Marshal Xiu was at Lunu and galloped north to pay his respects;" },
  { zh: "秀留署長史，與俱北至薊。", literal: "Xiu retained him as acting Chief Clerk and went north together to Ji.", idiomatic: "Xiu kept him as acting chief clerk and went north with him to Ji." },
  { zh: "王郎移檄購秀十萬戶，秀令功曹令史穎川王霸至市中募人擊王郎，市人皆大笑，舉手邪揄之，霸慚懅而反。", literal: "Wang Lang moved a proclamation offering a hundred thousand households for Xiu; Xiu ordered Merit Officer Clerk Yingchuan Wang Ba to the market to recruit men against Wang Lang—the townspeople all laughed, raising hands to mock him; Ba returned ashamed and fearful.", idiomatic: "Wang Lang issued a proclamation offering a reward of a hundred thousand households for Xiu; Xiu sent his merit officer Wang Ba of Yingchuan to the market to recruit men against Wang Lang—the townspeople all laughed and gestured in mockery, and Ba returned ashamed and afraid." },
  { zh: "秀將南歸，耿弇曰：「今兵從南方來，不可南行。", literal: "Xiu was about to return south; Geng Yan said: \"Now troops come from the south—we cannot go south.", idiomatic: "As Xiu was about to return south, Geng Yan said, \"Troops are coming up from the south—we cannot go south." },
  { zh: "漁陽太守彭寵，公之邑人；", literal: "Yuyang Administrator Peng Chong is your townsman;", idiomatic: "Yuyang Administrator Peng Chong is a fellow townsman of yours;" },
  { zh: "上谷太守，即弇父也。", literal: "the Shanggu Administrator is my father.", idiomatic: "and the Shanggu Administrator is my father." },
  { zh: "發此兩郡控弦萬騎，邯鄲不足慮也。", literal: "Raise from these two commanderies ten thousand mounted archers—Handan is not worth worrying over.", idiomatic: "Raise ten thousand mounted archers from these two commanderies, and Handan need not worry you.\"" },
  { zh: "」秀官屬腹心皆不肯，曰：「死尚南首，奈何北行入囊中！", literal: "\" Xiu's close aides all refused: \"Even in death we face south—how go north into a sack!", idiomatic: "\" Xiu's closest aides all refused, saying, \"Even in death we face south—how can we go north into the enemy's bag!\"" },
  { zh: "」秀指弇曰：「是我北道主人也。", literal: "\" Xiu pointed at Yan: \"He is my host for the northern road.", idiomatic: "\" Xiu pointed at Yan and said, \"He is my guide on the northern road.\"" },
  { zh: "會故廣陽王子接起兵薊中以應郎，城內擾亂，言邯鄲使者方到，二千石以下皆出迎。", literal: "Just then the former Prince of Guangyang Liu Jie raised troops in Ji to respond to Lang; the city was disturbed—said Handan envoys were arriving—all officials from two thousand piculs down went out to welcome.", idiomatic: "Just then the former Prince of Guangyang, Liu Jie, raised troops in Ji to support Lang; the city fell into turmoil, word spread that Handan envoys were arriving, and every official from two-thousand-picul rank down went out to welcome them." },
  { zh: "於是秀趣駕而出，至南城門，門已閉。", literal: "Thereupon Xiu urged his carriage out; reaching the south gate—the gate was already closed.", idiomatic: "Thereupon Xiu urged his carriage out; at the south gate the gate was already shut." },
  { zh: "攻之，得出。", literal: "They attacked it and got out.", idiomatic: "They forced it open and got out." },
  { zh: "遂晨夜南馳，不敢入城邑，捨食道傍。", literal: "Then day and night they galloped south, dared not enter cities, lodged by the roadside.", idiomatic: "Then they galloped south day and night, dared not enter any walled town, and lodged beside the road." },
  { zh: "至蕪蔞亭，時天寒烈，馮異上豆粥。", literal: "Reaching Wulou post; the weather was bitterly cold—Feng Yi served bean porridge.", idiomatic: "At Wulou post the cold was fierce; Feng Yi served bean porridge." },
  { zh: "至饒陽，官屬皆乏食。", literal: "Reaching Raoyang—all officials lacked food.", idiomatic: "At Raoyang all his followers lacked food." },
  { zh: "秀乃自稱邯鄲使者，入傳捨，傳吏方進食，從者饑，爭奪之。", literal: "Xiu then called himself a Handan envoy, entered the relay lodge—the clerk was just serving food; followers were hungry and snatched at it.", idiomatic: "Xiu then posed as a Handan envoy and entered the relay station; the clerk was just serving a meal, and his hungry followers snatched at the food." },
  { zh: "傳吏疑其偽，乃椎鼓數十通，紿言「邯鄲將軍至」，官屬皆失色。", literal: "The relay clerk suspected fraud, beat the drum dozens of rounds, falsely cried \"Handan general arrives\"—all officials turned pale.", idiomatic: "The relay clerk suspected the fraud, beat the drum dozens of times, and falsely announced, \"The Handan general has arrived\"—all the followers turned pale." },
  { zh: "秀升車欲馳，既而懼不免，徐還坐，曰：「請邯鄲將軍入。", literal: "Xiu mounted to flee, then feared he could not escape, slowly returned to sit: \"Please let the Handan general enter.", idiomatic: "Xiu mounted his carriage to flee, then feared he could not escape, slowly returned to his seat, and said, \"Please let the Handan general enter.\"" },
  { zh: "」久，乃駕去。", literal: "\" After long while they drove away.", idiomatic: "\" After a long while they drove away." },
  { zh: "晨夜兼行，蒙犯霜雪，面皆破裂。", literal: "Day and night double-marched, braved frost and snow—faces all cracked.", idiomatic: "They marched day and night through frost and snow until their faces were cracked and raw." },
  { zh: "至下曲陽，傳聞王郎兵在後，從者皆恐。", literal: "Reaching Xiaquyang—rumor that Wang Lang's troops were behind; followers all feared.", idiomatic: "At Xiaquyang word came that Wang Lang's troops were behind them, and all his followers were afraid." },
  { zh: "至滹沱河，候吏還白「河水流澌，無船，不可濟」。", literal: "Reaching Hutuo River—the scout returned reporting \"river ice flowing, no boats, cannot cross.\"", idiomatic: "At the Hutuo River the scout returned and reported, \"The river ice is breaking up, there are no boats, and it cannot be crossed.\"" },
  { zh: "秀使王霸往視之。", literal: "Xiu sent Wang Ba to look.", idiomatic: "Xiu sent Wang Ba to inspect it." },
  { zh: "霸恐驚眾，欲且前，阻水還，即詭曰：「冰堅可度。", literal: "Ba feared alarming the crowd, wished to advance first—blocked by water returned, immediately lied: \"Ice is solid—we can cross.", idiomatic: "Ba feared alarming the party, wished to go ahead first, was blocked by the water and returned, and at once lied, \"The ice is firm and we can cross.\"" },
  { zh: "」官屬皆喜。", literal: "\" Officials all rejoiced.", idiomatic: "\" All the followers rejoiced." },
  { zh: "秀笑曰：「候吏果妄語也。", literal: "Xiu laughed: \"The scout truly spoke falsely.", idiomatic: "Xiu laughed and said, \"The scout truly spoke falsely.\"" },
  { zh: "」遂前。", literal: "\" and advanced.", idiomatic: "\" and they went forward." },
  { zh: "比至河，河冰亦合，乃令王霸護度，未畢數騎而冰解。", literal: "When they reached the river the ice had also frozen solid; he ordered Wang Ba to supervise the crossing—not finished when several riders had crossed the ice broke.", idiomatic: "By the time they reached the river the ice had frozen solid again; he ordered Wang Ba to supervise the crossing, and before it was finished, after only a few horsemen had crossed, the ice broke up." },
  { zh: "至南宮，遇大風雨，秀引車入道傍空捨，馮異抱薪，鄧禹爇火，秀對灶燎衣，馮異復進麥飯。", literal: "Reaching Nangong—met great wind and rain; Xiu drew the carriage into an empty house by the road; Feng Yi carried firewood, Deng Yu lit fire; Xiu dried clothes by the stove; Feng Yi again served wheat meal.", idiomatic: "At Nangong they met violent wind and rain; Xiu drew his carriage into an empty house by the road, Feng Yi carried firewood, Deng Yu lit a fire, Xiu dried his clothes by the stove, and Feng Yi again served wheat meal." },
  { zh: "進至下博城西，惶惑不知所之。", literal: "Advancing to west of Xiabo city—distressed, not knowing where to go.", idiomatic: "Advancing to west of Xiabo, he was distressed and did not know where to go." },
  { zh: "有白衣老父在道旁，指曰：「努力！", literal: "A white-clad old man by the road pointed: \"Press on!", idiomatic: "A white-clad old man by the road pointed and said, \"Press on!" },
  { zh: "信都郡為長安城守，去此八十里。", literal: "Xindu commandery holds the city for Chang'an—eighty li from here.", idiomatic: "Xindu commandery is holding the city for Chang'an—eighty li from here.\"" },
  { zh: "」秀即馳赴之。", literal: "\" Xiu immediately galloped there.", idiomatic: "\" Xiu immediately galloped there." },
  { zh: "是時郡國皆已降王郎，獨信都太守南陽任光、和戎太守信都邳肜不肯從。", literal: "Then all commanderies had submitted to Wang Lang—only Xindu Administrator Nanyang Ren Guang and Herong Grand Protector Xindu Pi Yin refused.", idiomatic: "By then every commandery had submitted to Wang Lang; only Xindu Administrator Ren Guang of Nanyang and Herong Grand Protector Pi Yin of Xindu refused to follow." },
  { zh: "光自以孤城獨守，恐不能全，聞秀至，大喜，吏民皆稱萬歲。", literal: "Guang thought alone holding one city he feared could not preserve it; hearing Xiu arrived—great joy; officials and people all cried ten thousand years.", idiomatic: "Guang, thinking himself alone in one city and fearing he could not hold out, was overjoyed when he heard Xiu had come, and officials and people all cried, \"Long live the emperor!\"" },
  { zh: "邳肜亦自和戎來會，議者多言可因信都兵自送，西還長安。", literal: "Pi Yin also came from Herong to meet; councillors mostly said they could rely on Xindu troops to escort themselves west back to Chang'an.", idiomatic: "Pi Yin also came from Herong to join him; many advisers said they could rely on Xindu's troops to escort them west back to Chang'an." },
  { zh: "邳肜曰：「吏民歌吟思漢久矣，故更始舉尊號而天下響應，三輔清宮除道以迎之。", literal: "Pi Yin said: \"Officials and people have long sung longing for Han—therefore when Gengshi raised the exalted title the realm responded; the three adjuncts cleared palaces and swept roads to welcome him.", idiomatic: "Pi Yin said, \"Officials and people have long sung of longing for Han; that is why when Gengshi raised the imperial title the realm answered, and the Three Adjuncts cleared the palaces and swept the roads to welcome him." },
  { zh: "今卜者王郎，假名因勢，驅集烏合之眾，遂振燕、趙之地，無有根本之固。", literal: "Now the diviner Wang Lang—borrowing a name, riding momentum—drove together a mob, then shook Yan and Zhao lands—he has no deep root.", idiomatic: "Now the diviner Wang Lang, borrowing a name and riding momentum, has driven together a mob and shaken Yan and Zhao, but he has no deep foundation." },
  { zh: "明公奮二郡之兵以討之，何患不克！", literal: "Your Excellency rouses two commanderies' troops to campaign—what worry of not conquering!", idiomatic: "If Your Excellency rouses the troops of these two commanderies to campaign against him, what worry is there of not conquering him!" },
  { zh: "今釋此而歸，豈徒空失河北，必更驚動三輔，墮損威重，非計之得者也。", literal: "Now abandon this and return—not merely vainly losing Hebei—you will surely further alarm the three adjuncts, fall and damage authority—not a winning plan.", idiomatic: "If you abandon this now and return, you will not merely lose Hebei in vain—you will surely alarm the Three Adjuncts again and damage your authority; that is no winning plan." },
  { zh: "若明公無復征伐之意，則雖信都之兵，猶難會也。", literal: "If Your Excellency has no further intent to campaign—even Xindu's troops will be hard to gather.", idiomatic: "If Your Excellency has no further intent to campaign, then even Xindu's troops will be hard to gather." },
  { zh: "何者？", literal: "Why?", idiomatic: "Why?" },
  { zh: "明公既西，則邯鄲勢成，民不肯捐父母、背成主而千里送公，其離散亡逃可必也！", literal: "Your Excellency once west—then Handan's power is established; the people will not abandon parents, turn from accomplished lord to send you a thousand li—their scattering and flight is certain!", idiomatic: "Once Your Excellency goes west, Handan's power will be established; the people will not abandon their parents and turn from their established lord to escort you a thousand li—their scattering and flight is certain!\"" },
  { zh: "」秀乃止。", literal: "\" Xiu then stopped.", idiomatic: "\" Xiu then stopped." },
  { zh: "秀以二郡兵弱，欲入城頭子路、力子都軍中，任光以為不可。", literal: "Xiu because the two commanderies' troops were weak wished to enter Chengtou Zilu's and Li Zidu's armies; Ren Guang thought it impossible.", idiomatic: "Because the troops of the two commanderies were weak, Xiu wished to join the armies of Chengtou Zilu and Li Zidu, but Ren Guang thought that impossible." },
  { zh: "乃發傍縣，得精兵四千人，拜任光為左大將軍，信都都尉李忠為右大將軍，邳肜為後大將軍、和戎太守如故，信都令萬修為偏將軍，皆封列侯。", literal: "Then mobilized neighboring counties—got crack troops four thousand; appointed Ren Guang Left Grand General, Xindu Commandant Li Zhong Right Grand General, Pi Yin Rear Grand General and Herong Administrator as before, Xindu Magistrate Wan Xiu Partial General—all enfeoffed as ranked marquises.", idiomatic: "He then mobilized neighboring counties and got four thousand crack troops; he appointed Ren Guang Left Grand General, Xindu Commandant Li Zhong Right Grand General, Pi Yin Rear Grand General while keeping him as Herong Administrator, Xindu Magistrate Wan Xiu as Partial General, and enfeoffed them all as ranked marquises." },
  { zh: "留南陽宗廣領信都太守事；", literal: "Left Nanyang Zong Guang to oversee Xindu Administrator affairs;", idiomatic: "He left Zong Guang of Nanyang to oversee Xindu as acting administrator;" },
  { zh: "使任光、李忠、萬修將兵以從，邳肜將兵居前。", literal: "sent Ren Guang, Li Zhong, Wan Xiu to lead troops following; Pi Yin led troops in front.", idiomatic: "sent Ren Guang, Li Zhong, and Wan Xiu to lead troops after him, and Pi Yin to lead troops in the van." },
  { zh: "任光乃多作檄文曰：「大司馬劉公將城頭子路、力子都兵百萬眾從東方來，擊諸反虜！", literal: "Ren Guang then made many proclamations: \"Grand Marshal Lord Liu will lead Chengtou Zilu and Li Zidu—a million host from the east—to strike all rebels!", idiomatic: "Ren Guang then drafted many proclamations saying, \"Grand Marshal Liu will lead the armies of Chengtou Zilu and Li Zidu—a million men from the east—to strike all rebels!\"" },
  { zh: "」遣騎馳至巨鹿界中。", literal: "\" sent riders galloping into Julu territory.", idiomatic: "\" and sent riders galloping into Julu territory." },
  { zh: "吏民得檄，傳相告語。", literal: "Officials and people receiving proclamations passed word to one another.", idiomatic: "Officials and people who received the proclamations passed the word from one to another." },
  { zh: "秀投暮入堂陽界，多張騎火，彌滿澤中，堂陽即降；", literal: "Xiu at dusk entered Tangyang territory—spread many rider fires filling the marshes; Tangyang immediately surrendered;", idiomatic: "At dusk Xiu entered Tangyang territory, spread many horsemen's fires filling the marshes, and Tangyang surrendered at once;" },
  { zh: "又擊貰縣，降之。", literal: "again attacked Zhi county and reduced it.", idiomatic: "he then attacked Zhi county and reduced it." },
  { zh: "城頭子路者，東平爰曾也，寇掠河、濟間，有眾二十餘萬，力子都有眾六七萬，故秀欲依之。", literal: "Chengtou Zilu was Dongping Yuan Zeng—raided between Yellow River and Ji—had a host of more than two hundred thousand; Li Zidu had sixty or seventy thousand—therefore Xiu wished to rely on them.", idiomatic: "Chengtou Zilu was Yuan Zeng of Dongping, who had raided between the Yellow River and the Ji and had a host of more than two hundred thousand; Li Zidu had sixty or seventy thousand—therefore Xiu wished to rely on them." },
  { zh: "昌城人劉植聚兵數千人據昌城，迎秀；", literal: "Changcheng man Liu Zhi gathered troops several thousand, held Changcheng, welcomed Xiu;", idiomatic: "Liu Zhi of Changcheng gathered several thousand men, held Changcheng, and welcomed Xiu;" },
  { zh: "秀以植為驍騎將軍。", literal: "Xiu made Zhi Valiant Cavalry General.", idiomatic: "Xiu made Zhi Valiant Cavalry General." },
  { zh: "耿純率宗族賓客二千餘人，老病者皆載木自隨，迎秀於育；", literal: "Geng Chun led clan and retainers more than two thousand—old and sick all carried logs on themselves—welcomed Xiu at Yu;", idiomatic: "Geng Chun led more than two thousand clansmen and retainers; the old and sick all carried logs with them, and welcomed Xiu at Yu;" },
  { zh: "拜純為前將軍。", literal: "appointed Chun Front General.", idiomatic: "Xiu appointed Chun Front General." },
  { zh: "進攻下曲陽，降之。", literal: "advanced to attack Xiaquyang and reduced it.", idiomatic: "He advanced to attack Xiaquyang and reduced it." },
  { zh: "眾稍合，至數萬人，復北擊中山。", literal: "forces gradually combined to tens of thousands; again north to strike Zhongshan.", idiomatic: "His forces gradually combined to tens of thousands, and he again marched north to strike Zhongshan." },
  { zh: "耿純恐宗家懷異心，乃使從弟訢宿歸，燒廬舍以絕其反顧之望。", literal: "Geng Chun feared the clan might harbor other intent—sent cousin Xin Su home to burn houses and cut off thoughts of turning back.", idiomatic: "Geng Chun feared his clan might waver, so he sent his cousin Xin Su home to burn their houses and cut off any thought of turning back." },
  { zh: "秀進拔盧奴，所過發奔命兵，移檄邊郡共擊邯鄲；", literal: "Xiu advanced and took Lunu—wherever he passed raised urgent-service troops, moved proclamations to border commanderies jointly to strike Handan;", idiomatic: "Xiu advanced and took Lunu; wherever he passed he raised emergency troops and issued proclamations to the border commanderies to join in striking Handan;" },
  { zh: "郡縣還復響應。", literal: "commanderies and counties again responded.", idiomatic: "and commanderies and counties again answered his call." },
  { zh: "時真定王楊起兵附王郎，眾十餘萬，秀遣劉植說楊，楊乃降。", literal: "Then Prince of Zhending Yang raised troops and attached to Wang Lang—host over a hundred thousand; Xiu sent Liu Zhi to persuade Yang—Yang then surrendered.", idiomatic: "At that time the Prince of Zhending, Yang, had raised troops and joined Wang Lang with a host of more than a hundred thousand; Xiu sent Liu Zhi to persuade him, and Yang surrendered." },
  { zh: "秀因留真定，納楊甥郭氏為夫人以結之。", literal: "Xiu therefore stayed at Zhending, took Yang's nephew's daughter Guo as consort to bind him.", idiomatic: "Xiu therefore stayed at Zhending and took Yang's nephew's daughter Guo as his consort to bind him." },
  { zh: "進擊元氏、防子，皆下之。", literal: "advanced to strike Yuanshi and Fangzi—both taken.", idiomatic: "He advanced against Yuanshi and Fangzi and took them both." },
  { zh: "至鄗，擊斬王郎將李惲；", literal: "reaching Ye, struck and beheaded Wang Lang's general Li Yun;", idiomatic: "At Ye he struck and beheaded Wang Lang's general Li Yun;" },
  { zh: "至柏人，復破郎將李育。", literal: "reaching Bo ren, again broke Lang's general Li Yu.", idiomatic: "at Bo ren he again defeated Lang's general Li Yu." },
  { zh: "育還保城；", literal: "Yu retreated to hold the city;", idiomatic: "Yu retreated to hold the city;" },
  { zh: "攻之，不下。", literal: "attacked it—could not take it.", idiomatic: "they attacked it but could not take it." },
  { zh: "南鄭人延岑起兵據漢中，漢中王嘉擊降之，有眾數十萬。", literal: "Nanzheng man Yan Cen raised troops and held Hanzhong; King of Hanzhong Wang Jia attacked and reduced him—had a host of hundreds of thousands.", idiomatic: "Yan Cen of Nanzheng raised troops and seized Hanzhong; the King of Hanzhong, Wang Jia, attacked and reduced him and had a host of hundreds of thousands." },
  { zh: "校尉南陽賈復見更始政亂，乃說嘉曰：「今天下未定，而大王安守所保，所保得無不可保乎？", literal: "Commandant Nanyang Jia Fu seeing Gengshi's government chaotic persuaded Jia: \"Now the realm is not settled—yet Great King peacefully keeps what you hold—what you hold might it not become impossible to hold?", idiomatic: "Commandant Jia Fu of Nanyang, seeing Gengshi's government in chaos, urged Jia, \"The realm is not yet settled, yet Your Majesty sits peacefully on what you hold—might what you hold not prove impossible to hold?\"" },
  { zh: "」嘉曰：「卿言大，非吾任也。", literal: "\" Jia said: \"Your words are great—not my burden.", idiomatic: "\" Jia said, \"Your words are grand—not a burden I can bear." },
  { zh: "大司馬在河北，必能相用。", literal: "Grand Marshal is in Hebei—he can surely employ you.", idiomatic: "The Grand Marshal is in Hebei; he will surely be able to employ you.\"" },
  { zh: "」乃為書薦復及長史南陽陳俊於劉秀。", literal: "\" He then wrote recommending Fu and Chief Clerk Nanyang Chen Jun to Liu Xiu.", idiomatic: "\" He then wrote letters recommending Fu and his chief clerk Chen Jun of Nanyang to Liu Xiu." },
  { zh: "復等見秀於柏人，秀以復為破虜將軍，俊為安集掾。", literal: "Fu and others met Xiu at Bo ren; Xiu made Fu Bandit-Smashing General, Jun Pacification Aide.", idiomatic: "Fu and his party met Xiu at Bo ren; Xiu made Fu Bandit-Smashing General and Jun Pacification Aide." },
  { zh: "秀捨中兒犯法，軍市令穎川祭遵格殺之，秀怒，命收遵。", literal: "Xiu's household boy broke the law—Army Market Officer Yingchuan Ji Zun executed him by regulation; Xiu was angry and ordered Zun seized.", idiomatic: "One of Xiu's household boys broke the law; Army Market Officer Ji Zun of Yingchuan executed him according to regulation; Xiu was angry and ordered Zun seized." },
  { zh: "主簿陳副諫曰：「明公常欲眾軍整齊，今遵奉法不避，是教令所行也。", literal: "Chief Clerk Chen Fu remonstrated: \"Your Excellency always wished the hosts orderly—now Zun upheld law without shrinking—this is what orders require.", idiomatic: "Chief Clerk Chen Fu remonstrated, \"Your Excellency always wished the armies kept in order; now Zun upheld the law without shrinking—this is what your orders require.\"" },
  { zh: "」乃貰之，以為刺奸將軍，謂諸將曰：「當備祭遵！", literal: "\" He then pardoned him, made him Bandit-Probing General, told the generals: \"Be wary of Ji Zun!", idiomatic: "\" He then pardoned him, made him Bandit-Probing General, and told the generals, \"Beware of Ji Zun!" },
  { zh: "吾捨中兒犯法尚殺之，必不私諸卿也。", literal: "Even my household boy breaking law was still killed—I surely will not favor you.", idiomatic: "Even when my own household boy broke the law I had him killed—I will surely not show favor to any of you.\"" },
  { zh: "初，王莽既殺鮑宣，上黨都尉路平欲殺其子永；", literal: "At first, after Wang Mang had killed Bao Xuan, Shangdang Commandant Lu Ping wished to kill his son Yong;", idiomatic: "Earlier, after Wang Mang had killed Bao Xuan, Shangdang Commandant Lu Ping wished to kill his son Yong;" },
  { zh: "太守苟諫保護之，永由是得全。", literal: "Administrator Gou Jian protected him—Yong thereby was preserved whole.", idiomatic: "but Administrator Gou Jian protected him, and Yong was thereby preserved." },
  { zh: "更始征永為尚書僕射，行大將軍事，將兵安集河東、并州，得自置偏裨。", literal: "Gengshi summoned Yong as Vice Director of the Masters of Writing, acting Grand General affairs, leading troops to pacify Hedong and Bing Province, could himself appoint deputies.", idiomatic: "Gengshi summoned Yong as Vice Director of the Masters of Writing with authority as acting grand general, to lead troops and pacify Hedong and Bing Province, with power to appoint his own deputies." },
  { zh: "永至河東，擊青犢，大破之。", literal: "Yong reached Hedong, struck the Green Calves, greatly broke them.", idiomatic: "When Yong reached Hedong he attacked the Green Calves and routed them." },
  { zh: "以馮衍為立漢將軍，屯太原，與上黨太守田邑等繕甲養士，以扞衛並土。", literal: "Made Feng Yan Establish-Han General, stationed at Taiyuan, with Shangdang Administrator Tian Yi and others repaired armor and nurtured soldiers to defend Bing soil.", idiomatic: "He made Feng Yan Establish-Han General, stationed him at Taiyuan, and with Shangdang Administrator Tian Yi and others repaired armor, nurtured troops, and defended the Bing region." },
  { zh: "或說大司馬秀以守柏人不如定巨鹿，秀乃引兵東北拔廣阿。", literal: "Some persuaded Grand Marshal Xiu that holding Bo ren was inferior to securing Julu—Xiu then led troops northeast and took Guang'a.", idiomatic: "Some urged Grand Marshal Xiu that holding Bo ren was inferior to securing Julu; Xiu then led his troops northeast and took Guang'a." },
  { zh: "秀披輿地圖，指示鄧禹曰：「天下郡國如是，今始乃得其一。", literal: "Xiu spread the carriage map, pointed for Deng Yu: \"The realm's commanderies are like this—we have only now obtained one.", idiomatic: "Xiu spread out the carriage map and pointed it out to Deng Yu, saying, \"The commanderies of the realm are like this—we have only now obtained one." },
  { zh: "子前言以吾慮天下不足定，何也？", literal: "You said before you thought I considered the realm not enough to settle—why?", idiomatic: "You said before that I thought the realm not yet ready to be settled—why was that?\"" },
  { zh: "」禹曰：「方今海內殽亂，人思明君，猶赤子之慕慈母。", literal: "\" Yu said: \"Now within the seas chaos—people think of a clear lord like an infant cherishing a loving mother.", idiomatic: "\" Yu said, \"Now the realm is in chaos within the four seas; the people long for a clear-sighted ruler, as an infant cherishes its mother.\"" },
  { zh: "古之興者在德薄厚，不以大小也。", literal: "Those who rose in antiquity depended on whether virtue was thick or thin—not on whether they were great or small.", idiomatic: "Those who rose in antiquity depended on whether virtue was thick or thin—not on whether they were great or small." },
  { zh: "」薊中之亂，耿弇與劉秀相失，北走昌平，就其父況，因說況擊邯鄲。", literal: "\" In the turmoil at Ji, Geng Yan and Liu Xiu lost one another; Yan fled north to Changping, joined his father Kuang, and thereby urged Kuang to attack Handan.", idiomatic: "In the turmoil at Ji, Geng Yan and Liu Xiu lost one another; Yan fled north to Changping, joined his father Kuang, and urged Kuang to attack Handan." },
  { zh: "時王郎遣將徇漁陽、上谷，急發其兵。", literal: "At the time Wang Lang sent generals to overrun Yuyang and Shanggu and urgently mobilized their troops.", idiomatic: "At the time Wang Lang sent generals to overrun Yuyang and Shanggu and urgently mobilized their troops." },
  { zh: "北州疑惑，多欲從之。", literal: "The northern provinces were doubtful and many wished to follow him.", idiomatic: "The northern provinces were doubtful, and many wished to follow him." },
  { zh: "上谷功曹寇恂、門下掾閔業說況曰：「邯鄲拔起，難可信向。", literal: "Shanggu's Merit Officer Kou Xun and Retainer Clerk Min Ye said to Kuang: \"Handan has sprung up—it is hard to trust and turn toward.", idiomatic: "Shanggu's Merit Officer Kou Xun and Retainer Clerk Min Ye said to Kuang, \"Handan has sprung up—it is hard to trust and turn toward.\"" },
  { zh: "大司馬，劉伯升母弟，尊賢下士，可以歸之。", literal: "The Grand Marshal is Bo Sheng Liu Yan's younger brother by the same mother; he honors the worthy and lowers himself before scholars—one can submit to him.", idiomatic: "The Grand Marshal is Bo Sheng Liu Yan's younger brother by the same mother; he honors the worthy and lowers himself before scholars—you can submit to him.\"" },
  { zh: "」況曰：「邯鄲方盛，力不能獨拒，如何？", literal: "\" Kuang said: \"Handan is at its height; our strength cannot alone resist—what then?", idiomatic: "Kuang said, \"Handan is at its height; our strength cannot alone resist—what then?\"" },
  { zh: "」對曰：「今上谷完實，控弦萬騎，可以詳擇去就。", literal: "\" They replied: \"Now Shanggu is intact and full, with ten thousand bowmen—we can carefully choose whether to go or stay.", idiomatic: "They replied, \"Now Shanggu is intact and full, with ten thousand bowmen—we can carefully choose whether to go or stay.\"" },
  { zh: "恂請東約漁陽，齊心合眾，邯鄲不足圖也！", literal: "Xun asks to go east and ally with Yuyang; with one heart joining the masses, Handan is not worth plotting against!", idiomatic: "Let Xun go east and ally with Yuyang; with one heart joining forces, Handan is not worth plotting against!\"" },
  { zh: "」況然之，遣恂東約彭寵，欲各發突騎二千匹、步兵千人詣大司馬秀。", literal: "\" Kuang assented and sent Xun east to ally with Peng Chong, wishing each to dispatch two thousand shock-cavalry horses and a thousand foot soldiers to Grand Marshal Xiu.", idiomatic: "Kuang assented and sent Xun east to ally with Peng Chong, wishing each to dispatch two thousand shock-cavalry horses and a thousand foot soldiers to Grand Marshal Liu Xiu." },
  { zh: "安樂令吳漢、護軍蓋延、狐奴令王梁亦勸寵從秀，寵以為然，而官屬皆欲附王郎，寵不能奪。", literal: "Anle magistrate Wu Han, Protector of the Army Gai Yan, and Hunu magistrate Wang Liang also urged Chong to follow Xiu; Chong thought it right, but his officials all wished to attach to Wang Lang, and Chong could not overrule them.", idiomatic: "Anle magistrate Wu Han, Protector of the Army Gai Yan, and Hunu magistrate Wang Liang also urged Chong to follow Liu Xiu; Chong thought it right, but his officials all wished to attach to Wang Lang, and Chong could not overrule them." },
  { zh: "漢出止外亭，遇一儒生，召而食之，問以所聞。", literal: "Han went out and stopped at an outer pavilion, met a Confucian scholar, summoned and fed him, and asked what he had heard.", idiomatic: "Wu Han went out and stopped at an outer pavilion, met a Confucian scholar, summoned and fed him, and asked what he had heard." },
  { zh: "生言：「大司馬劉公，所過為郡縣所稱，邯鄲舉尊號者，實非劉氏。", literal: "The scholar said: \"Grand Marshal Duke Liu—wherever he passes the commanderies and counties praise him; the one who raised an honorific title at Handan is in truth not of the Liu house.", idiomatic: "The scholar said, \"Grand Marshal Duke Liu—wherever he passes the commanderies and counties praise him; the one who raised an honorific title at Handan is in truth not of the Liu house.\"" },
  { zh: "」漢大喜，即詐為秀書，移檄漁陽，使生繼以詣寵，令具以所聞說之。", literal: "\" Han was greatly pleased, at once forged a letter in Xiu's name, and issued a proclamation to Yuyang, sending the scholar on to Chong and ordering him to explain in full what he had heard.", idiomatic: "Wu Han was greatly pleased, at once forged a letter in Liu Xiu's name and issued a proclamation to Yuyang, sending the scholar on to Chong and ordering him to explain in full what he had heard." },
  { zh: "會寇恂至，寵乃發步騎三千人，以吳漢行長史，與蓋延、王梁將之，南攻薊，殺王郎大將趙閎。", literal: "When Kou Xun arrived, Chong then dispatched three thousand foot and cavalry, with Wu Han acting as chief clerk, and with Gai Yan and Wang Liang leading them south to attack Ji, killing Wang Lang's great general Zhao Hong.", idiomatic: "When Kou Xun arrived, Chong then dispatched three thousand foot and cavalry, with Wu Han acting as chief clerk and Gai Yan and Wang Liang leading them south to attack Ji, killing Wang Lang's great general Zhao Hong." },
  { zh: "寇恂還，遂與上谷長史景丹及耿弇將兵俱南，與漁陽軍合，所過擊斬王郎大將、九卿、校尉以下，凡斬首三萬級，定涿郡、中山、巨鹿、清河、河間凡二十二縣。", literal: "Kou Xun returned, then with Shanggu Chief Clerk Jing Dan and Geng Yan led troops together south, united with the Yuyang army, and along the way struck and beheaded Wang Lang's great generals, Nine Ministers, and commandants and below—in all thirty thousand heads, securing Zhuo, Zhongshan, Julu, Qinghe, and Hejian, twenty-two counties in all.", idiomatic: "Kou Xun returned, then with Shanggu Chief Clerk Jing Dan and Geng Yan led troops south together, united with the Yuyang army, and along the way struck and beheaded Wang Lang's great generals, Nine Ministers, and commandants and below—in all thirty thousand heads—and secured Zhuo, Zhongshan, Julu, Qinghe, and Hejian, twenty-two counties in all." },
  { zh: "前及廣阿，聞城中車騎甚眾，丹等勒兵問曰：「此何兵？", literal: "Advancing to Guang'a, they heard that chariots and horsemen in the city were very numerous; Dan and the others reined the army and asked: \"What troops are these?", idiomatic: "Advancing to Guang'a, they heard that chariots and horsemen in the city were very numerous; Jing Dan and the others reined the army and asked, \"What troops are these?\"" },
  { zh: "」曰：「大司馬劉公也。", literal: "\" They said: \"It is Grand Marshal Duke Liu.", idiomatic: "They said, \"It is Grand Marshal Duke Liu.\"" },
  { zh: "」諸將喜，即進至城下。", literal: "\" The generals were pleased and at once advanced to below the wall.", idiomatic: "The generals were pleased and at once advanced to below the wall." },
  { zh: "城下初傳言二郡兵為邯鄲來，眾皆恐。", literal: "Below the wall at first it was rumored that the two commanderies' troops had come for Handan; the masses were all afraid.", idiomatic: "Below the wall at first it was rumored that the troops of the two commanderies had come for Handan; everyone was afraid." },
  { zh: "劉秀自登西城樓勒兵問之；", literal: "Liu Xiu himself ascended the western city tower, reined the troops, and questioned them;", idiomatic: "Liu Xiu himself ascended the western city tower, reined the troops, and questioned them;" },
  { zh: "耿弇拜於城下，即召入，具言發兵狀。", literal: "Geng Yan bowed below the wall and was at once summoned in, fully explaining the situation of raising troops.", idiomatic: "Geng Yan bowed below the wall and was at once summoned in, fully explaining how they had raised troops." },
  { zh: "秀乃悉召景丹等入，笑曰：「邯鄣將帥數言我發漁陽、上谷兵，吾聊應言『我亦發之』，何意二郡良為吾來！", literal: "Xiu then summoned Jing Dan and the others all in, laughed, and said: \"Handan's commanders repeatedly said I was raising Yuyang and Shanggu troops; I merely answered for the moment, 'I am raising them too'—who expected the two commanderies truly to come for me!", idiomatic: "Liu Xiu then summoned Jing Dan and the others all in, laughed, and said, \"Handan's commanders repeatedly said I was raising Yuyang and Shanggu troops; I merely answered for the moment, 'I am raising them too'—who expected the two commanderies truly to come for me!" },
  { zh: "方與士大夫共此功名耳。", literal: "I am just sharing this achievement with scholars and officials.", idiomatic: "I am just sharing this achievement with scholars and officials.\"" },
  { zh: "」乃以景丹、寇恂、耿弇、蓋延、吳漢、王梁皆為偏將軍，使還領其兵，加耿況、彭寵大將軍；", literal: "\" Thereupon he made Jing Dan, Kou Xun, Geng Yan, Gai Yan, Wu Han, and Wang Liang all partial generals, sent them back to command their troops, and advanced Geng Kuang and Peng Chong to great generals;", idiomatic: "Thereupon he made Jing Dan, Kou Xun, Geng Yan, Gai Yan, Wu Han, and Wang Liang all partial generals, sent them back to command their troops, and advanced Geng Kuang and Peng Chong to great generals;" },
  { zh: "封況、寵、丹、延皆為列侯。", literal: "he enfeoffed Kuang, Chong, Dan, and Yan all as ranked marquises.", idiomatic: "he enfeoffed Kuang, Chong, Dan, and Yan all as ranked marquises." },
  { zh: "吳漢為人，質厚少文，造次不能以辭自達，然沉勇有智略，鄧禹數薦之於秀，秀漸親重之。", literal: "Wu Han as a man was plain and thick, short on polish; in haste he could not express himself in words, yet he was deep, brave, and possessed strategy. Deng Yu repeatedly recommended him to Xiu, and Xiu gradually drew close to and valued him.", idiomatic: "Wu Han as a man was plain and unpolished; in haste he could not express himself in words, yet he was deep, brave, and possessed strategy. Deng Yu repeatedly recommended him to Liu Xiu, and Liu Xiu gradually drew close to and valued him." },
  { zh: "更始遣尚書令謝躬率六將軍討王郎，不能下。", literal: "Gengshi dispatched Minister Director Xie Gong leading six generals to attack Wang Lang and could not take him.", idiomatic: "Emperor Gengshi dispatched Minister Director Xie Gong leading six generals to attack Wang Lang and could not take him." },
  { zh: "秀至，與之合軍，東圍巨鹿，月餘未下。", literal: "When Xiu arrived he united armies with him, besieged Julu to the east, and for more than a month did not take it.", idiomatic: "When Liu Xiu arrived he united armies with him, besieged Julu to the east, and for more than a month did not take it." },
  { zh: "王郎遣將攻信都，大姓馬寵等開城內之。", literal: "Wang Lang sent generals to attack Xindu; great clans such as Ma Chong and others opened the city and admitted them.", idiomatic: "Wang Lang sent generals to attack Xindu; great clans such as Ma Chong and others opened the city and admitted them." },
  { zh: "更始遣兵攻破信都，秀使李忠還，行太守事。", literal: "Gengshi dispatched troops, broke Xindu, and Xiu sent Li Zhong back to act as acting grand administrator.", idiomatic: "Emperor Gengshi dispatched troops and retook Xindu; Liu Xiu sent Li Zhong back to act as acting grand administrator." },
  { zh: "王郎遣將倪宏、劉奉率數萬人救巨鹿，秀逆戰於南□，不利。", literal: "Wang Lang sent generals Ni Hong and Liu Feng leading tens of thousands to rescue Julu; Xiu met them in battle at Nan□ and fared ill.", idiomatic: "Wang Lang sent generals Ni Hong and Liu Feng leading tens of thousands to rescue Julu; Liu Xiu met them in battle at Nanhe and fared ill." },
  { zh: "景丹等縱突騎擊之，宏等大敗。", literal: "Jing Dan and the others unleashed shock cavalry to strike them; Hong and the others were greatly defeated.", idiomatic: "Jing Dan and the others unleashed shock cavalry to strike them; Hong and the others were routed." },
  { zh: "秀曰：「吾聞突騎天下精兵，今見其戰，樂可言邪？", literal: "Xiu said: \"I have heard shock cavalry are the realm's finest troops—now seeing them fight, can joy be put into words?", idiomatic: "Liu Xiu said, \"I have heard shock cavalry are the realm's finest troops—now seeing them fight, can joy be put into words?\"" },
  { zh: "」耿純言於秀曰：「久守巨鹿，士眾疲弊；", literal: "\" Geng Chun said to Xiu: \"Long besieging Julu—the soldiers and masses are weary and spent;", idiomatic: "Geng Chun said to Liu Xiu, \"A long siege of Julu has wearied the troops;" },
  { zh: "不如及大兵精銳，進攻邯鄲。", literal: "better while the great army is keen and sharp to advance and attack Handan.", idiomatic: "better while the great army is keen and sharp to advance and attack Handan." },
  { zh: "若王郎已誅，巨鹿不戰自服矣。", literal: "If Wang Lang is already executed, Julu will submit without fighting.", idiomatic: "If Wang Lang is already executed, Julu will submit without fighting.\"" },
  { zh: "」秀從之。", literal: "\" Xiu followed this.", idiomatic: "Liu Xiu followed this." },
  { zh: "夏，四月，留將軍鄧滿守巨鹿。", literal: "Summer, fourth month: he left General Deng Man to hold Julu.", idiomatic: "In summer, in the fourth month, he left General Deng Man to hold Julu." },
  { zh: "進軍邯鄲，連戰，破之。", literal: "He advanced the army to Handan, fought repeatedly, and broke them.", idiomatic: "He advanced the army to Handan, fought repeatedly, and broke them." },
  { zh: "郎乃使其諫大夫杜威請降。", literal: "Lang then sent his Remonstrance Grandee Du Wei to request surrender.", idiomatic: "Wang Lang then sent his Remonstrance Grandee Du Wei to request surrender." },
  { zh: "威雅稱郎實成帝遺體，秀曰：「設使成帝復生，天下不可得，況詐子輿者乎！", literal: "Wei elegantly claimed Lang was in truth Emperor Cheng's surviving body; Xiu said: \"Suppose Emperor Cheng were reborn—all under Heaven could not be obtained—how much less a fraud such as Ziyu!", idiomatic: "Du Wei elegantly claimed Wang Lang was in truth Emperor Cheng's surviving body; Liu Xiu said, \"Suppose Emperor Cheng were reborn—all under Heaven could not be obtained—how much less a fraud such as Ziyu!" },
  { zh: "」威請求萬戶侯，秀曰：「顧得全身可矣！", literal: "\" Wei requested to be made a marquis of ten thousand households; Xiu said: \"I only wish to preserve my whole body—that is enough!", idiomatic: "Du Wei requested to be made a marquis of ten thousand households; Liu Xiu said, \"I only wish to preserve my whole body—that is enough!\"" },
  { zh: "」威怒而去。", literal: "\" Wei left in anger.", idiomatic: "Du Wei left in anger." },
  { zh: "秀急攻之，二十餘日。", literal: "Xiu pressed the attack for more than twenty days.", idiomatic: "Liu Xiu pressed the attack for more than twenty days." },
  { zh: "五月，甲辰，郎少傅李立開門內漢兵，遂拔邯鄲。", literal: "Fifth month, day jiachen: Lang's Junior Tutor Li Li opened the gate and admitted the Han troops; Handan was then taken.", idiomatic: "In the fifth month, on the day jiachen, Wang Lang's Junior Tutor Li Li opened the gate and admitted the Han troops; Handan was then taken." },
  { zh: "郎夜亡走，王霸追斬之。", literal: "Lang fled by night; Wang Ba pursued and beheaded him.", idiomatic: "Wang Lang fled by night; Wang Ba pursued and beheaded him." },
  { zh: "秀收郎文書，得吏民與郎交關謗毀者數千章。", literal: "Xiu gathered Lang's documents and obtained several thousand memorials from officials and commoners who had dealings with Lang and slandered others.", idiomatic: "Liu Xiu gathered Wang Lang's documents and obtained several thousand memorials from officials and commoners who had dealings with Wang Lang and slandered others." },
  { zh: "秀不省，會諸將軍燒之，曰：「令反側子自安！", literal: "Xiu did not examine them; he assembled the generals and burned them, saying: \"Let those who waver calm themselves!", idiomatic: "Liu Xiu did not examine them; he assembled the generals and burned them, saying, \"Let those who waver calm themselves!\"" },
  { zh: "」秀部分吏卒各隸諸軍，士皆言願屬大樹將軍。", literal: "\" Xiu assigned officials and soldiers each to the various armies; the soldiers all said they wished to belong to the Big Tree General.", idiomatic: "Liu Xiu assigned officials and soldiers each to the various armies; the soldiers all said they wished to belong to the Big Tree General." },
  { zh: "大樹將軍者，偏將軍馮異也，為人謙退不伐，敕吏士非交戰受敵，常行諸營之後。", literal: "The Big Tree General was Partial General Feng Yi; as a man he was modest and retiring and did not boast, ordering officials and soldiers that unless in battle receiving the enemy they should always march behind the various camps.", idiomatic: "The Big Tree General was Partial General Feng Yi; as a man he was modest and retiring and did not boast, ordering officials and soldiers that unless in battle receiving the enemy they should always march behind the various camps." },
  { zh: "每所止捨，諸將並坐論功，異常獨屏樹下，故軍中號曰：「大樹將軍」。", literal: "Whenever he halted, the generals all sat together discussing merit while Yi alone regularly stood apart under a tree; therefore in the army he was styled \"Big Tree General.\"", idiomatic: "Whenever he halted, the generals all sat together discussing merit while Feng Yi alone regularly stood apart under a tree; therefore in the army he was styled \"Big Tree General.\"" },
  { zh: "護軍宛人朱祜從容言於秀曰：「長安政亂，公有日角之相，此天命也！", literal: "Protector of the Army Zhu Hu of Wan said at ease to Xiu: \"Chang'an's government is in disorder; Your Grace has the physiognomy of a sun-horn—this is Heaven's mandate!", idiomatic: "Protector of the Army Zhu Hu of Wan said at ease to Liu Xiu, \"Chang'an's government is in disorder; Your Grace has the physiognomy of a sun-horn—this is Heaven's mandate!\"" },
  { zh: "」秀曰：「召刺奸收護軍！", literal: "\" Xiu said: \"Summon the Investigator of Misconduct and take the Protector of the Army!", idiomatic: "Liu Xiu said, \"Summon the Investigator of Misconduct and take the Protector of the Army!\"" },
  { zh: "」祜乃不敢復言。", literal: "\" Hu then did not dare speak again.", idiomatic: "Zhu Hu then did not dare speak again." },
  { zh: "更始遣使立秀為蕭王，悉令罷兵，與諸將有功者詣行在所。", literal: "Gengshi dispatched envoys to establish Xiu as Prince of Xiao, ordered all to disband the army, and that he and the generals who had merit should proceed to the mobile court.", idiomatic: "Emperor Gengshi dispatched envoys to establish Liu Xiu as Prince of Xiao, ordered all to disband the army, and that he and the meritorious generals should proceed to the mobile court." },
  { zh: "遣苗曾為幽州牧，韋順為上谷太守，蔡充為漁陽太守，並北之部。", literal: "He dispatched Miao Zeng as Regional Governor of Youzhou, Wei Shun as Grand Administrator of Shanggu, and Cai Chong as Grand Administrator of Yuyang, all to go north to their departments.", idiomatic: "He dispatched Miao Zeng as Regional Governor of Youzhou, Wei Shun as Grand Administrator of Shanggu, and Cai Chong as Grand Administrator of Yuyang, all to go north to their departments." },
  { zh: "蕭王居邯鄲宮，晝臥溫明殿，耿弇入，造床下請間，因說曰：「吏士死傷者多，請歸上谷益兵。", literal: "The Prince of Xiao dwelt in Handan's palace, napping by day in the Hall of Warm Brightness; Geng Yan entered, came below the couch to request a private audience, and thereby said: \"Officials and soldiers dead and wounded are many—I ask to return to Shanggu to augment the army.", idiomatic: "The Prince of Xiao dwelt in Handan's palace, napping by day in the Hall of Warm Brightness; Geng Yan entered, came below the couch to request a private audience, and said, \"Officials and soldiers dead and wounded are many—I ask to return to Shanggu to augment the army.\"" },
  { zh: "」蕭王曰：「王郎已破，河北略平，復用兵何為？", literal: "\" The Prince of Xiao said: \"Wang Lang is already broken; Hebei is largely pacified—why use arms again?", idiomatic: "The Prince of Xiao said, \"Wang Lang is already broken; Hebei is largely pacified—why use arms again?\"" },
  { zh: "」弇曰：「王郎雖破，天下兵革乃始耳。", literal: "\" Yan said: \"Though Wang Lang is broken, arms and armor under Heaven have only just begun.", idiomatic: "Geng Yan said, \"Though Wang Lang is broken, arms and armor under Heaven have only just begun." },
  { zh: "今使者從西方來，欲罷兵，不可聽也。", literal: "Now envoys come from the west wishing to disband the army—this cannot be obeyed.", idiomatic: "Now envoys come from the west wishing to disband the army—this cannot be obeyed." },
  { zh: "銅馬、赤眉之屬數十輩，輩數十百萬人，所向無前，聖公不能辦也，敗必不久。", literal: "The Bronze Horses, Red Eyebrows, and their sort number several tens of bands, each band several hundred thousand or a million men; wherever they aim none stands before them. Sheng Gong cannot deal with them—defeat will surely come soon.", idiomatic: "The Bronze Horses, Red Eyebrows, and their sort number several tens of bands, each band several hundred thousand or a million men; wherever they aim none stands before them. Emperor Gengshi cannot deal with them—defeat will surely come soon.\"" },
  { zh: "」蕭王起坐曰：「卿失言，我斬卿！", literal: "\" The Prince of Xiao sat up and said: \"You misspeak—I will behead you!", idiomatic: "The Prince of Xiao sat up and said, \"You misspeak—I will behead you!\"" },
  { zh: "」弇曰：「大王哀厚弇如父子，故敢披赤心。", literal: "\" Yan said: \"Your Highness pities and favors Yan as father to son—therefore I dare lay bare my red heart.", idiomatic: "Geng Yan said, \"Your Highness pities and favors me as father to son—therefore I dare lay bare my red heart.\"" },
  { zh: "」蕭王曰：「我戲卿耳，何以言之？", literal: "\" The Prince of Xiao said: \"I was jesting with you—why do you say this?", idiomatic: "The Prince of Xiao said, \"I was jesting with you—why do you say this?\"" },
  { zh: "」弇曰：「百姓患苦王莽，復思劉氏，聞漢兵起，莫不歡喜，如去虎口得歸慈母。", literal: "\" Yan said: \"The hundred surnames suffered under Wang Mang and again long for the Liu house; hearing Han troops rise, none are not delighted—as if leaving a tiger's maw to return to a loving mother.", idiomatic: "Geng Yan said, \"The people suffered under Wang Mang and again long for the Liu house; hearing Han troops rise, none are not delighted—as if leaving a tiger's maw to return to a loving mother." },
  { zh: "今更始為天子，而諸將擅命於山東，貴戚縱橫於都內，虜掠自恣，元元叩心，更思莽朝，是以知其必敗也。", literal: "Now Gengshi is Son of Heaven, yet the generals act on their own authority east of the mountains, noble kin run rampant within the capital, plundering as they please; the masses beat their breasts and again think of Mang's court—thereby one knows he must fail.", idiomatic: "Now Emperor Gengshi is Son of Heaven, yet the generals act on their own authority east of the mountains, noble kin run rampant within the capital and plunder as they please; the masses beat their breasts and again think of Wang Mang's court—thereby one knows he must fail." },
  { zh: "公功名已著，以義征伐，天下可傳檄而定也。", literal: "Your Grace's achievement and fame are already manifest; with righteous campaigning all under Heaven can be settled by passing proclamations alone.", idiomatic: "Your Grace's achievement and fame are already manifest; with righteous campaigning all under Heaven can be settled by passing proclamations alone." },
  { zh: "天下至重，公可自取，毋令他姓得之。", literal: "All under Heaven is supremely weighty—Your Grace can take it yourself; do not let another surname obtain it.", idiomatic: "All under Heaven is supremely weighty—Your Grace can take it yourself; do not let another surname obtain it.\"" },
  { zh: "」蕭王乃辭以河北未平，不就征，始貳於更始。", literal: "\" The Prince of Xiao then declined on the grounds that Hebei was not yet pacified, did not answer the summons, and for the first time turned against Gengshi.", idiomatic: "The Prince of Xiao then declined on the grounds that Hebei was not yet pacified, did not answer the summons, and for the first time turned against Emperor Gengshi." },
  { zh: "是時，諸賊銅馬、大彤、高湖、重連、鐵脛、大槍、尤來、上江、青犢、五校、五幡、五樓、富平、獲索等各領部曲，眾合數百萬人，所在寇掠。", literal: "At this time the various bandits—the Bronze Horses, Great Scarlet, High Lakes, Repeated Links, Iron Shins, Great Spears, Youlai, Upper River, Green Calves, Five Schools, Five Banners, Five Towers, Fuping, Huosuo, and others—each led their followings; the masses together numbered several million men, raiding wherever they were.", idiomatic: "At this time the various bandits—the Bronze Horses, Great Scarlet, High Lakes, Repeated Links, Iron Shins, Great Spears, Youlai, Upper River, Green Calves, Five Schools, Five Banners, Five Towers, Fuping, Huosuo, and others—each led their followings; together they numbered several million men and raided wherever they were." },
  { zh: "蕭王欲擊之，乃拜吳漢、耿弇俱為大將軍，持節北發幽州十郡突騎。", literal: "The Prince of Xiao wished to attack them and therefore appointed Wu Han and Geng Yan both as great generals, bearing credentials north to mobilize shock cavalry from Youzhou's ten commanderies.", idiomatic: "The Prince of Xiao wished to attack them and therefore appointed Wu Han and Geng Yan both as great generals, bearing credentials north to mobilize shock cavalry from Youzhou's ten commanderies." },
  { zh: "苗曾聞之，陰敕諸郡不得應調。", literal: "Miao Zeng heard of this and secretly ordered the commanderies not to answer the mobilization.", idiomatic: "Miao Zeng heard of this and secretly ordered the commanderies not to answer the mobilization." },
  { zh: "吳漢將二十騎先馳至無終，曾出迎於路，漢即收曾，斬之。", literal: "Wu Han with twenty horsemen galloped ahead to Wuzhong; Zeng came out to welcome him on the road, and Han at once seized Zeng and beheaded him.", idiomatic: "Wu Han with twenty horsemen galloped ahead to Wuzhong; Zeng came out to welcome him on the road, and Wu Han at once seized Zeng and beheaded him." },
  { zh: "耿弇到上谷，亦收韋順、蔡充，斬之。", literal: "Geng Yan reached Shanggu and also seized Wei Shun and Cai Chong and beheaded them.", idiomatic: "Geng Yan reached Shanggu and also seized Wei Shun and Cai Chong and beheaded them." },
  { zh: "北州震駭，於是悉發其兵。", literal: "The northern provinces were shaken in terror; thereupon they all mobilized their troops.", idiomatic: "The northern provinces were shaken in terror; thereupon they all mobilized their troops." },
  { zh: "秋，蕭王擊銅馬於鄡，吳漢將突騎來會清陽，士馬甚盛，漢悉上兵簿於莫府，請所付與，不敢自私，王益重之。", literal: "Autumn: the Prince of Xiao attacked the Bronze Horses at Mao; Wu Han led shock cavalry to join him at Qingyang—the soldiers and horses were very strong. Han submitted all troop registers to the headquarters and requested assignment, not daring to be selfish; the prince valued him the more.", idiomatic: "In autumn the Prince of Xiao attacked the Bronze Horses at Mao; Wu Han led shock cavalry to join him at Qingyang—the soldiers and horses were very strong. Wu Han submitted all troop registers to headquarters and requested assignment, not daring to be selfish; the prince valued him the more." },
  { zh: "王以偏將軍沛國朱浮為大將軍、幽州牧，使治薊城。", literal: "The prince made Partial General Zhu Fu of Pei great general and Regional Governor of Youzhou, sending him to govern Jicheng.", idiomatic: "The prince made Partial General Zhu Fu of Pei great general and Regional Governor of Youzhou, sending him to govern Jicheng." },
  { zh: "銅馬食盡，夜遁，蕭王追擊於館陶，大破之。", literal: "The Bronze Horses' food was exhausted; they fled by night; the Prince of Xiao pursued and attacked at Guantao and routed them.", idiomatic: "The Bronze Horses' food was exhausted; they fled by night; the Prince of Xiao pursued and attacked at Guantao and routed them." },
  { zh: "受降未盡，而高湖、重連從東南來，與銅馬餘眾合。", literal: "Surrenders were not yet complete when High Lakes and Repeated Links came from the southeast and united with the Bronze Horses' remaining masses.", idiomatic: "Surrenders were not yet complete when High Lakes and Repeated Links came from the southeast and united with the Bronze Horses' remaining forces." },
  { zh: "蕭王復與大戰於蒲陽，悉破降之，封其渠帥為列侯。", literal: "The Prince of Xiao again fought a great battle at Puyang, completely broke and accepted their surrender, and enfeoffed their chieftains as ranked marquises.", idiomatic: "The Prince of Xiao again fought a great battle at Puyang, completely broke and accepted their surrender, and enfeoffed their chieftains as ranked marquises." },
  { zh: "諸將未能信賊，降者亦不自安。", literal: "The generals could not yet trust the bandits; the surrendered also were not themselves at ease.", idiomatic: "The generals could not yet trust the bandits; the surrendered also were not at ease." },
  { zh: "王知其意，敕令降者各歸營勒兵，自乘輕騎按行部陳。", literal: "The prince knew their intent, ordered the surrendered each to return to camp and rein the troops, and himself rode light cavalry to inspect and walk through the formations.", idiomatic: "The prince knew their intent, ordered the surrendered each to return to camp and rein the troops, and himself rode light cavalry to inspect the formations." },
  { zh: "降者更相語曰：「蕭王推赤心置人腹中，安得不投死乎！", literal: "The surrendered said to one another: \"The Prince of Xiao sets his red heart in men's bellies—how can we not throw ourselves to death for him!", idiomatic: "The surrendered said to one another, \"The Prince of Xiao sets his red heart in men's bellies—how can we not throw ourselves to death for him!" },
  { zh: "」由是皆服。", literal: "\" Thereby all submitted.", idiomatic: "Thereby all submitted." },
  { zh: "悉以降人分配諸將，眾遂數十萬。", literal: "He assigned all the surrendered to the various generals; the masses then reached several hundred thousand.", idiomatic: "He assigned all the surrendered to the various generals; his forces then reached several hundred thousand." },
  { zh: "赤眉別帥與青犢、上江、大彤、鐵脛、五幡十餘萬眾在射犬，蕭王引兵進擊，大破之。", literal: "A Red Eyebrow splinter commander with Green Calves, Upper River, Great Scarlet, Iron Shins, and Five Banners—more than a hundred thousand masses—were at Shequan; the Prince of Xiao led troops forward to attack and routed them.", idiomatic: "A Red Eyebrow splinter commander with Green Calves, Upper River, Great Scarlet, Iron Shins, and Five Banners—more than a hundred thousand men—were at Shequan; the Prince of Xiao led troops forward to attack and routed them." },
  { zh: "南徇河內，河內太守韓歆降。", literal: "He marched south through Henei; Henei Grand Administrator Han Xin surrendered.", idiomatic: "He marched south through Henei; Henei Grand Administrator Han Xin surrendered." },
  { zh: "初，謝躬與蕭王共滅王郎，數與蕭王違戾，常欲襲蕭王，畏其兵強而止。", literal: "At first Xie Gong and the Prince of Xiao together destroyed Wang Lang; they repeatedly clashed with the prince, often wished to strike him, but feared his troops were strong and stopped.", idiomatic: "At first Xie Gong and the Prince of Xiao together destroyed Wang Lang; they repeatedly clashed with the prince, often wished to strike him, but feared his troops were strong and stopped." },
  { zh: "雖俱在邯鄲，遂分城而處，然蕭王每有以慰安之。", literal: "Though both were at Handan they then divided the city and dwelt apart, yet the Prince of Xiao always had means to comfort and reassure him.", idiomatic: "Though both were at Handan they then divided the city and dwelt apart, yet the Prince of Xiao always had means to comfort and reassure him." },
  { zh: "躬勤於吏職，蕭王常稱之曰：「謝尚書，真吏也！", literal: "Gong was diligent in official duties; the Prince of Xiao often praised him, saying: \"Minister Xie is a true official!", idiomatic: "Xie Gong was diligent in official duties; the Prince of Xiao often praised him, saying, \"Minister Xie is a true official!" },
  { zh: "」故不自疑。", literal: "\" Therefore he did not suspect himself.", idiomatic: "Therefore he did not suspect himself." },
  { zh: "其妻知之，常戒之曰：「君與劉公積不相能，而信其虛談，終受制矣。", literal: "His wife knew this and often warned him: \"You and Duke Liu have long been incompatible, yet you trust his empty talk—you will in the end be controlled.", idiomatic: "His wife knew this and often warned him, \"You and Duke Liu have long been incompatible, yet you trust his empty talk—you will in the end be controlled.\"" },
  { zh: "」躬不納。", literal: "\" Gong did not accept this.", idiomatic: "Xie Gong did not accept this." },
  { zh: "既而躬率其兵數萬還屯於鄴。", literal: "Before long Gong led his troops, several tens of thousands, back to encamp at Ye.", idiomatic: "Before long Xie Gong led his troops, several tens of thousands, back to encamp at Ye." },
  { zh: "及蕭王南擊青犢，使躬邀擊尤來於隆慮山，躬兵大敗。", literal: "When the Prince of Xiao attacked Green Calves south he sent Gong to intercept Youlai at Longlu Mountain; Gong's army was greatly defeated.", idiomatic: "When the Prince of Xiao attacked Green Calves south he sent Xie Gong to intercept Youlai at Longlu Mountain; Xie Gong's army was routed." },
  { zh: "蕭王因躬在外，使吳漢與刺奸大將軍岑彭襲據鄴城。", literal: "The Prince of Xiao, because Gong was abroad, sent Wu Han and Investigator of Misconduct Great General Cen Peng to raid and seize Ye.", idiomatic: "The Prince of Xiao, because Xie Gong was abroad, sent Wu Han and Investigator of Misconduct Great General Cen Peng to raid and seize Ye." },
  { zh: "躬不知，輕騎還鄴，漢等收斬之，其眾悉降。", literal: "Gong did not know; he returned to Ye with light cavalry; Han and the others seized and beheaded him, and his masses all surrendered.", idiomatic: "Xie Gong did not know; he returned to Ye with light cavalry; Wu Han and the others seized and beheaded him, and his troops all surrendered." },
  { zh: "更始遣柱功侯李寶、益州刺史張忠將兵萬餘人徇蜀、漢。", literal: "Gengshi dispatched Pillar of Merit Marquis Li Bao and Regional Inspector of Yizhou Zhang Zhong leading more than ten thousand troops to overrun Shu and Han.", idiomatic: "Emperor Gengshi dispatched Pillar of Merit Marquis Li Bao and Regional Inspector of Yizhou Zhang Zhong leading more than ten thousand troops to overrun Shu and Han." },
  { zh: "公孫述遣其弟恢擊寶、忠於綿竹，大破走之。", literal: "Gongsun Shu sent his younger brother Hui to strike Bao and Zhong at Mianzhu, routed them, and drove them off.", idiomatic: "Gongsun Shu sent his younger brother Hui to strike Li Bao and Zhang Zhong at Mianzhu, routed them, and drove them off." },
  { zh: "述遂自立為蜀王，都成都，民、夷皆附之。", literal: "Shu thereupon declared himself King of Shu, made Chengdu his capital, and both commoners and Yi all attached themselves to him.", idiomatic: "Gongsun Shu thereupon declared himself King of Shu, made Chengdu his capital, and both commoners and barbarians attached themselves to him." },
  { zh: "冬，更始遣中郎將歸德侯颯、大司馬護軍陳遵使匈奴，授單于漢舊制璽綬，因送雲、當餘親屬、貴人、從者還匈奴。", literal: "In winter, Gengshi sent Gentleman of the Palace Marquis of Guide Hou Sa and Grand Marshal's Protector of the Army Chen Zun as envoys to the Xiongnu, conferring on the Shanyu the Han old-style seal and ribbon, and thereby sending back to the Xiongnu the kin, nobles, and followers left over from Yun and Dang.", idiomatic: "In winter, Emperor Gengshi sent Gentleman of the Palace Marquis of Guide Hou Sa and Grand Marshal's Protector of the Army Chen Zun as envoys to the Xiongnu, conferring upon the Shanyu the Han old-style seal and ribbon, and thereby sending back to the Xiongnu the kin, nobles, and followers left over from the Yun and Dang affair." },
  { zh: "單于輿驕，謂遵、颯曰：「匈奴本與漢為兄弟，匈奴中亂，孝宣皇帝輔立呼韓邪單于，故稱臣以尊漢。", literal: "The Shanyu Yu was arrogant and said to Zun and Sa: \"The Xiongnu originally were brothers with Han; when the Xiongnu fell into turmoil within, Emperor Xiaoxuan assisted and established Shanyu Huhanye, therefore he styled himself subject to honor Han.", idiomatic: "Shanyu Yu was arrogant and said to Chen Zun and Hou Sa, \"The Xiongnu were originally brothers with Han; when the Xiongnu fell into internal turmoil, Emperor Xiaoxuan assisted and established Shanyu Huhanye, and therefore he styled himself a subject to honor Han.\"" },
  { zh: "今漢亦大亂，為王莽所篡，匈奴亦出兵擊莽，空其邊境，令天下騷動思漢；", literal: "Now Han too is greatly in turmoil, usurped by Wang Mang; the Xiongnu also sent troops to strike Mang, emptied his borderlands, and made all under Heaven disturbed and longing for Han;", idiomatic: "Now Han too is in great turmoil and was usurped by Wang Mang; the Xiongnu also sent troops to strike Mang, emptied his borderlands, and made all under Heaven disturbed and longing for Han;" },
  { zh: "莽卒以敗而漢復興，亦我力也，當復尊我！", literal: "Mang in the end was defeated and Han revived—this too was my strength; you ought again to honor me!", idiomatic: "Mang in the end was defeated and Han revived—this too was my doing; you ought again to honor me!\"" },
  { zh: "」遵與相撐拒，單于終持此言。", literal: "\" Zun argued back and forth with him; the Shanyu in the end held to this saying.", idiomatic: "Chen Zun argued back and forth with him; the Shanyu in the end held to this position." },
  { zh: "赤眉樊崇等將兵入穎川，分其眾為二部，崇與逢安為一部，徐宣、謝祿、楊音為一部。", literal: "The Red Eyebrows Fan Chong and others led troops into Yingchuan, divided their masses into two divisions—Chong with Feng An as one division, Xu Xuan, Xie Lu, and Yang Yin as one division.", idiomatic: "Fan Chong and the other Red Eyebrows led troops into Yingchuan and divided their forces into two divisions—Chong with Feng An in one, Xu Xuan, Xie Lu, and Yang Yin in the other." },
  { zh: "赤眉雖數戰勝，而疲敝厭兵，皆日夜愁泣，思欲東歸。", literal: "Though the Red Eyebrows repeatedly won battles, they were worn out and weary of war; all by day and night grieved and wept, thinking to return east.", idiomatic: "Though the Red Eyebrows had repeatedly won battles, they were worn out and weary of war; all day and night they grieved and wept, longing to return east." },
  { zh: "崇等計議，慮眾東向必散，不如西攻長安。", literal: "Chong and the others deliberated, fearing that if the masses turned east they would surely scatter—better to attack west toward Chang'an.", idiomatic: "Chong and the others deliberated, fearing that if the troops turned east they would surely scatter; it would be better to attack west toward Chang'an." },
  { zh: "於是崇、安自武關，宣等從陸渾關，兩道俱入。", literal: "Thereupon Chong and An by Wu Pass, Xuan and the others by Luhun Pass—both routes entered together.", idiomatic: "Thereupon Chong and An entered by Wu Pass while Xuan and the others entered by Luhun Pass—the two columns advanced together." },
  { zh: "更始使王匡、成丹與抗威將軍劉均等分據河東、弘農以拒之。", literal: "Gengshi sent Wang Kuang, Cheng Dan, and Resist-the-Mighty General Liu Jun to hold separately Hedong and Hongnong to resist them.", idiomatic: "Emperor Gengshi sent Wang Kuang, Cheng Dan, and Resist-the-Mighty General Liu Jun to hold Hedong and Hongnong separately to resist them." },
  { zh: "蕭王將北徇燕、趙，度赤眉必破長安，又欲乘釁並關中，而未知所寄，乃拜鄧禹為前將軍，中分麾下精兵二萬人，遣西入關，令自選偏裨以下可與俱者。", literal: "The Duke of Xiao was about to march north through Yan and Zhao, reckoned the Red Eyebrows would surely break Chang'an, and also wished to seize the opportunity to annex Guanzhong, yet did not know whom to entrust; he therefore appointed Deng Yu as Forward General, divided from the center of his command two ten thousand crack troops, and sent him west to enter the passes, ordering him to choose himself which subordinate officers and below might go with him.", idiomatic: "The Duke of Xiao was about to march north through Yan and Zhao, reckoned the Red Eyebrows would surely take Chang'an, and also wished to seize the opportunity to annex Guanzhong, yet did not know whom to entrust; he therefore appointed Deng Yu as Forward General, gave him twenty thousand crack troops from his own command, and sent him west into the passes, letting him choose which subordinate officers and men might accompany him." },
  { zh: "時朱鮪、李軼、田立、陳僑將兵號三十萬，與河南太守武勃共守洛陽；", literal: "At the time Zhu Wei, Li Yi, Tian Li, and Chen Qiao led troops styled at three hundred thousand, and together with Administrator of Henan Wu Bo jointly held Luoyang;", idiomatic: "At the time Zhu Wei, Li Yi, Tian Li, and Chen Qiao led troops said to number three hundred thousand and, together with Administrator of Henan Wu Bo, held Luoyang;" },
  { zh: "鮑永、田邑在并州。", literal: "Bao Yong and Tian Yi were in Bingzhou.", idiomatic: "Bao Yong and Tian Yi were in Bingzhou." },
  { zh: "蕭王以河內險要富實，欲擇諸將守河內者而難其人，問於鄧禹。", literal: "The Duke of Xiao, because Henei was strategically vital and rich and substantial, wished to choose among the generals one to hold Henei but found the man difficult; he asked Deng Yu.", idiomatic: "The Duke of Xiao, because Henei was strategically vital and rich, wished to choose a general to hold it but could not settle on the right man, and asked Deng Yu." },
  { zh: "鄧禹曰：「寇恂文武備足，有牧民御眾之才，非此子莫可使也！", literal: "Deng Yu said: \"Kou Xun is complete in civil and martial arts, has the talent to shepherd the people and control the masses—none but this man can be sent!", idiomatic: "Deng Yu said, \"Kou Xun is complete in civil and martial arts and has the talent to govern the people and command troops—none but this man should be sent!\"" },
  { zh: "」乃拜恂河內太守，行大將軍事。", literal: "\" He thereupon appointed Xun Administrator of Henei, acting Grand General affairs.", idiomatic: "He thereupon appointed Kou Xun Administrator of Henei with the powers of a grand general." },
  { zh: "蕭王謂恂曰：「昔高祖留蕭何關中，吾今委公以河內。", literal: "The Duke of Xiao said to Xun: \"Formerly Gaozu left Xiao He in Guanzhong; I now entrust you with Henei.", idiomatic: "The Duke of Xiao said to Kou Xun, \"Formerly Gaozu left Xiao He in Guanzhong; I now entrust you with Henei.\"" },
  { zh: "當給足軍糧，率厲士馬，防遏它兵，勿令北度而已！", literal: "You ought to supply sufficient army grain, lead and encourage soldiers and horses, block other armies—only do not let them cross north!", idiomatic: "You must supply sufficient army grain, lead and encourage soldiers and horses, and block other armies—only do not let them cross the river north!\"" },
  { zh: "」拜馮異為孟津將軍，統魏郡、河內兵於河上，以拒洛陽。", literal: "\" He appointed Feng Yi as Mengjin General, commanding the troops of Wei commandery and Henei on the river to resist Luoyang.", idiomatic: "He appointed Feng Yi as Mengjin General, commanding the troops of Wei commandery and Henei on the river to resist Luoyang." },
  { zh: "蕭王親送鄧禹至野王，禹既西，蕭王乃復引兵而北。", literal: "The Duke of Xiao personally escorted Deng Yu to Yewang; once Yu had gone west, the Duke of Xiao again led troops north.", idiomatic: "The Duke of Xiao personally escorted Deng Yu to Yewang; once Yu had gone west, the Duke of Xiao again led his army north." },
  { zh: "寇恂調餱糧、治器械以供軍；", literal: "Kou Xun adjusted dry provisions and prepared weapons to supply the army;", idiomatic: "Kou Xun levied dry provisions and prepared weapons to supply the army;" },
  { zh: "軍雖遠征，未嘗乏絕。", literal: "though the army was on distant campaigns, it never lacked or was cut off.", idiomatic: "though the army was on distant campaigns, it was never short of supplies." },
  { zh: "隗崔、隗義謀叛歸天水。", literal: "Wei Cui and Wei Yi plotted rebellion to return to Tianshui.", idiomatic: "Wei Cui and Wei Yi plotted to rebel and return to Tianshui." },
  { zh: "隗囂恐並及禍，乃告之。", literal: "Wei Ao feared being implicated in the calamity and therefore informed on them.", idiomatic: "Wei Ao feared being implicated in the calamity and informed on them." },
  { zh: "更始誅崔、義，以囂為御史大夫。", literal: "Gengshi executed Cui and Yi and made Ao Censor-in-Chief.", idiomatic: "Emperor Gengshi executed Cui and Yi and made Wei Ao Censor-in-Chief." },
  { zh: "梁王永據國起兵，招諸郡豪桀，沛人周建等並署為將帥，攻下濟陰、山陽、沛、楚、淮陽、汝南，凡得二十八城。", literal: "Liang Wang Yong, holding his state, raised troops, recruited heroic stalwarts of the various commanderies; Zhou Jian of Pei and others were all appointed as commanders, attacked and took Jiyin, Shanyang, Pei, Chu, Huaiyang, and Runan—in all twenty-eight cities.", idiomatic: "Liang Wang Yong, holding his domain, raised troops and recruited local heroes of the various commanderies; Zhou Jian of Pei and others were all appointed commanders, attacked and took Jiyin, Shanyang, Pei, Chu, Huaiyang, and Runan—in all twenty-eight cities." },
  { zh: "又遣使拜西防賊帥山陽佼強為橫行將軍，東海賊帥董憲為翼漢大將軍，琅邪賊帥張步為輔漢大將軍，督青、徐二州，與之連兵，遂專據東方。", literal: "He again sent envoys to appoint Xifang bandit chief Jiao Qiang of Shanyang as Crosswise Marching General, Donghai bandit chief Dong Xian as Aid-Han Grand General, and Langye bandit chief Zhang Bu as Assist-Han Grand General, supervising Qing and Xu two provinces; joining forces with them, he thereupon monopolized the east.", idiomatic: "He again sent envoys to appoint Xifang bandit chief Jiao Qiang of Shanyang as Crosswise Marching General, Donghai bandit chief Dong Xian as Aid-Han Grand General, and Langye bandit chief Zhang Bu as Assist-Han Grand General, supervising Qing and Xu; joining forces with them, he thereupon held the east exclusively." },
  { zh: "已阜人秦豐起兵於黎丘，攻得已阜、宜城等十餘縣，有眾萬人，自號楚黎王。", literal: "Qin Feng, a man of Yifu, raised troops at Liqiu, attacked and obtained Yifu, Yicheng, and more than ten counties, had masses of ten thousand, and styled himself King Chu-Li.", idiomatic: "Qin Feng of Yifu raised troops at Liqiu, attacked and took Yifu, Yicheng, and more than ten counties, mustered ten thousand men, and styled himself King Chu-Li." },
  { zh: "汝南田戎攻陷夷陵，自稱掃地大將軍；", literal: "Tian Rong of Runan attacked and took Yiling, styled himself Sweep-the-Earth Grand General;", idiomatic: "Tian Rong of Runan attacked and took Yiling and styled himself Sweep-the-Earth Grand General;" },
  { zh: "轉寇郡縣，眾數萬人。", literal: "he turned to raid commanderies and counties; his masses numbered several tens of thousands.", idiomatic: "he then raided commanderies and counties until his forces numbered several tens of thousands." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
